import{m as g}from"./cet6ListeningSeriesFactory-85tJrEqr.js";const c=JSON.parse(`[{"id":"c6-08-dialogue-a","paperNumber":8,"kind":"conversation","title":"Lesson 18: Flour Baby, Part 2","date":"2019-01-26","sourceUrl":"https://learningenglish.voanews.com/a/lets-learn-english-level-2-lesson-18/4231290.html","publisher":"VOA Learning English","credit":"VOA Learning English — Let’s Learn English Level 2 original intermediate teaching dialogue, including grammar instruction.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2018/01/31/16d806b3-f878-4eff-bd6e-1857ec1241e0.mp3","audioUrl":"/audio/mock-cet6-series/c6-08-dialogue-a.mp3","audioBytes":2064443,"publisherAudioBytes":2064443,"audioSha256":"7c123f3aa69e06d53dd5403256e7cbfdbc228bf5ad16c2d8dc6aecf9b01833af","sourceSha256":"0dfafce35721947fac8c63073ed21b91ff92c1b787d758f01d36e80bfa1fdff5","paragraphs":["Professor Bot: In Part 1 of this two-part lesson, Ms. Weaver gave Anna and Pete an assignment. Ms. Weaver instructed them to do everything by themselves.","“Themselves” is a reflexive pronoun.","In today’s lesson, Ms. Weaver will look at Pete’s and Anna’s research. First, let’s see Pete’s experiment.","(Pete throws the bag of flour on his chair and throws many other things on his flour baby. Next, we see him outside enjoying ice-cream without his flour baby.)","Ms. Weaver: Okay, Pete, let me see your research first.","(Pete hands her a big binder filled with research.)","Ms. Weaver: That’s a heavy binder. And you and your Baby look great.","Pete: Thanks, Ms. Weaver. We feel great!","Ms. Weaver: Anna. Anna, you’re next. Anna? Anna wake up!","(She wakes up but is very confused.)","Anna: I'm here, Baby! I’m here! I’m here! Here's your bottle.","(She accidentally squirts her bottle and milk goes everywhere.)","Ms. Weaver: Anna, you and your baby look awful. What happened?","Anna: Well, I took her everywhere. Everywhere. And I fed her every three hours. So, I haven’t slept since … what day is it?","Ms. Weaver: It’s Friday. What happened there?","(Ms. Weaver points to a large bandage on Anna’s flour baby.)","Anna: Oh, that. Oh, that. I was making myself a salad and had a little accident with a knife . I put my flour baby in front of me. And then I accidentally stabbed it. But I gave it First Aid !","Ms. Weaver: Is that a burn ?","Anna: Yes. Yes it is. While I was making myself dinner, I put Baby next to me. I accidentally knocked her into the sink. So I put her in the microwave to dry . That’s when she caught fire.","(Pete smiles, thinking he’s won.)","Professor Bot: Okay. So, we use a reflexive pronoun when it refers to the subject of a sentence or clause.","But we DON’T use a reflexive pronoun with prepositions of place.","Anna uses examples of both in one sentence: While I was making myself dinner, I put Baby next to me .","We use a reflexive pronoun in the first part of the sentence. “Myself” refers to the subject “I.”","But in the second part of the sentence, we don’t use a reflexive pronoun in the prepositional phrase. We use the pronoun “me.” Why? “next to” is a preposition of place.","(Back in the meeting room, we’re about to learn who won the parenting experiment. Pete is smiling, thinking he won.)","Ms. Weaver: Anna, Anna, you should be very proud of yourself.","Pete: Proud? She stabbed and burned her baby!! And she only did one page of research…and it’s covered in milk. Ew.","Ms. Weaver: Yes, Pete. But she followed instructions.","Pete: Hey, I did ...","Ms. Weaver: Please, Pete. Anna, I think your baby has lost some weight. Is there something else you want to share?","Anna: Yes. I’d like to share … these! I made them myself this morning.","Pete: You baked your baby? You should be ashamed of yourself!","Anna: I baked them at the end of the experiment, Pete. At that point, this was just a bag of flour.","Pete: It was always just a bag of flour!!","Ms. Weaver: Pete, will you listen to yourself ?! You sound crazy.","Pete: I sound crazy! This whole experiment was crazy!! She was the one who carried around and fed it and ...","(Anna puts a cookie into his mouth. He chews it and begins to smile.)","Pete: Mmm. That is good.","(They all agree and eat the cookies.)","Professor Bot: So, what have we learned? We’ve learned when to use reflexive pronouns and when not to.","Go to our website for more information! You can practice using reflexive pronouns in our comments section."],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-08-dialogue-b","paperNumber":8,"kind":"conversation","title":"Lesson 20: The Test Drive","date":"2019-02-10","sourceUrl":"https://learningenglish.voanews.com/a/lets-learn-english-level-2-lesson-20/4254704.html","publisher":"VOA Learning English","credit":"VOA Learning English — Let’s Learn English Level 2 original intermediate teaching dialogue, including grammar instruction.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2018/02/15/8b42c321-07ea-4eb1-a1f9-e7cc6019606e.mp3","audioUrl":"/audio/mock-cet6-series/c6-08-dialogue-b.mp3","audioBytes":2253916,"publisherAudioBytes":2253916,"audioSha256":"de1af8c0e51b2bf48622142e17e9de2dbc271ca52181f5596d776bac22acfdcb","sourceSha256":"f36cd1923536bfbb1879b011a756e63bd15abc1bf770b258f8282504f2873548","paragraphs":["Anna: (to Penelope) That’s a great idea. (to Rick) Rick, I think we should use this as the opening shot .","Penelope: Anna, did Ms. Weaver give us instructions for covering the car show?","Anna: She did. She said that we need to show lots of cars. She said we need to interview people . And she also said that we should have fun.","Penelope: Those were her exact words?","Anna: Yeah. She said, “Have fun, Anna!” And she is the boss.","Anna: (to Rick) Okay, Rick, are you - are you ready? OK. Hello, I'm Anna Matteo. Welcome to the Washington Car Show!","Anna: People all over town are saying that if you like cars, this is the place to be ! So, let's see what people are talking about. (at Rick) How was that? Okay? Is that Good?","Professor Bot: Anna, Penelope and Rick are making a news story about the Washington Car Show. Ms. Weaver gave them instructions.","We often need to tell others what someone else said.","There are two ways to do this. One is to use the person’s exact words and use quotation marks. We call this \\"direct speech.\\"","For example, Ms. Weaver had said, “You need to show lots of cars.”","The other way is to talk about what someone said. We call this \\"reported speech.\\"","Anna tells Penelope: She said that we need to show lots of cars.","In this sentence, \\"she,\\" is the subject, “said” is the reporting verb, “that” is the conjunction and “we need to show lots of cars” is the reporting clause.","Keep watching, and listen for sentences where Anna talks about what someone else said!","Anna: This car show has many styles of vehicles . There are utility vehicles , classic cars , trucks, sports cars , and everyday vehicles.","Penelope: Okay, I think we got good interviews.","Anna: Me too! People had very different opinions . But they all said they loved cars .","Penelope: Anna, look -- a robot!","Anna: A robot!","Penelope: A robot!","Anna: Rick, we have to use the robot in the show!","(They walk over to the robot. Anna begins to dance like a robot.)","Robot: What is your first name?","Anna: Anna! Anna!","Robot: Anna, you know, what an effort . What an effort to robot dance. How about a round of applause for Anna! I’ve never seen anyone try so hard.","Anna: Penelope, did you hear that? Hank the Robot said that he has never seen anyone dance like me.","Penelope: Uh, I think many people here are saying that, Anna.","Anna: That was fun. You know what someone told me? You can test drive a Jaguar at this car show.","Penelope: Now, that sounds fun.","Anna: Let’s go.","Penelope: Okay.","Anna: This course is smooth . So you can drive faster.","Anna: He said...that I can’t drive, unfortunately .","(They begin the test drive. Kurt, the stunt driver , does the driving.)","Anna: Oh my gosh… reverse.","Anna: That was great. This is awesome.","Kurt: Are you ready to go on the rollercoaster ?","Anna: I’m ready.","Kurt: Here we go!","Anna: That’s awesome.","Anna: That was...That was awesome! I just want to go one more time. I promise. That’s it. Just one more time.","Anna: This course is bumpy and uneven . I was told that I could drive this course. So I am.","Anna: (to Rick) Okay, Rick, are you rolling ? Awesome. Okay, this course is uneven. But I think the ride will be smooth.","Anna: Ooh. This hill is really steep .","Anna: Oh my gosh. I can’t tell you how much fun this is.","Anna: Penelope, that was so much fun! I think I need to go again.","Penelope: Uh, Anna, I think we have enough test drive video.","Anna: Ms. Weaver said to get a lot. So, I think I should go again. (to Rick) Rick, I’m going to go again. Until next time!","Penelope: But I want to get lunch, Anna!","Professor Bot: Penelope said she wants to go to lunch . But I don’t think that’s going to happen soon. Visit our website for more!"],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-08-passage-a","paperNumber":8,"kind":"passage","title":"Naturalists Use Phones to 'Capture' Animals","date":"2017-06-10","sourceUrl":"https://learningenglish.voanews.com/a/naturalists-use-their-phones-to-capture-animals/3888122.html","publisher":"VOA Learning English","credit":"VOA Science and Agriculture Correspondent Steve Baragona reported this story from Arlington, Virginia. Christopher Jones-Cruise adapted the report for Learning English. Caty Weaver was the editor.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2017/06/06/814edc87-9bf0-4644-b325-39dc483ee746.mp3","audioUrl":"/audio/mock-cet6-series/c6-08-passage-a.mp3","audioBytes":1806121,"publisherAudioBytes":1806121,"audioSha256":"5270b687c3398ef98f9ce0b03b7cff59ed5ba3991d144709f1bcc3381de5e00f","sourceSha256":"adde43e47c0213d9e530e10fe0feadb9839b0d710fed3d260825da033b4eb907","paragraphs":["A smartphone program is helping scientists learn about changes taking place in nature. More than 100,000 citizen-scientists around the world are taking pictures of many kinds of plants and animals using a program called iNaturalist.","The program gives researchers large amounts of information about where plants and animals live, and how a growing human population is changing plant and animal life.","In Arlington, Virginia, experts and volunteers are making a record of the plants and animals that live in the heavily populated area. VOA followed them as they worked on a recent day.","Alonso Abugattas is the local government’s natural resources manager. He works to protect and improve Arlington’s natural spaces.","“Everyone knows that if you want to protect something, you’ve got to know what you have.”","The group is using the iNaturalist smartphone program to record its observations. Then iNaturalist users throughout the world can look at the images and try to help identify it.","The program records where and when the picture was taken. This lets experts like Abugattas and others create maps that show where plants and animals are living, and how that changes because of development and climate change.","“Are some things that we had then no longer here? Are some things that we never knew we had now popping back up? And that will give us a gauge of how good or how poorly we’re doing as far as being stewards .”","That is important in Arlington and around the world. Scott Loarie is co-director of iNaturalist. He spoke to VOA on Skype. He said species are dying at a faster rate than ever, and the mix of life on Earth is threatened.","“And we’ve only begun to understand exactly how those ecosystems contribute to our food system, or human health -- all these things that we depend on.”","Loarie says iNaturalist lets citizen-scientists help professional scientists gather data.","More than 100,000 iNaturalist observers on all seven continents have made more than four-and-a-half million observations.","The information has been used in studies of monarch butterflies, bats that may carry Ebola, and other animals.","Alonso Abugattas says the group in Arlington recorded more than 450 kinds of animals and plants.","“If you just open up your eyes to the natural world, you’d be amazed at what’s out there.”","I’m Lucija Millonig."],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-08-passage-b","paperNumber":8,"kind":"passage","title":"Rising Seas Force Changes on Historic Farms","date":"2018-11-11","sourceUrl":"https://learningenglish.voanews.com/a/rising-seas-force-changes-on-historic-farms/4638771.html","publisher":"VOA Learning English","credit":"VOA’s Steve Baragona reported this story. Susan Shand adapted his story for Learning English. George Grow was the editor.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2018/11/01/0afe0083-390a-4569-8177-eb1cd727777a.mp3","audioUrl":"/audio/mock-cet6-series/c6-08-passage-b.mp3","audioBytes":2584765,"publisherAudioBytes":2584765,"audioSha256":"f190436df6f0781b79c61b776c1e07d71aee5ab7d9245eed39f45359c69e23fe","sourceSha256":"6d3ca9cc33ffa1c5bce79b74469f60a1d5cca7314ca0b1a549c91a929318c37b","paragraphs":["Looking out the window of his Ford truck, Bob Fitzgerald sees large, undesirable plants growing in the fields.","Visitors to his neighborhood in Princess Anne, Maryland mainly see dying forests and empty farmland.","Fitzgerald says the land has been in his family since the 17 th century.","\\"I'd say in the next 20 years, you're going to lose a very high percentage of that land, that's going to be unfit to farm.\\"","The land around the Chesapeake Bay has been sinking for hundreds of years. But climate change is making things worse. As sea levels rise, salt water is entering rivers and other waterways. As a result, the ground is becoming too salty for crops to grow.","Maryland's Eastern Shore is home to some of the oldest farms in North America. Fitzgerald's dates back to 1666. He says he has seen big changes during his life.","\\"You just can't believe how it's taking things over in the last 15 or 20 years. I can show you land around here that people raised tomatoes on when I was a little boy. And now it's gone.\\"","Around the world, scientists warn that coastal farms are under threat from rising seas and salt water. A World Bank report estimates that rice production in coastal areas of Bangladesh may fall by 15 percent by the year 2050. Another study found that hundreds of millions of people will be forced to move inland because of rising waters.","Kate Tully wants to keep Eastern Shore farmers in business as the seas rise.","Tully is an agroecologist with the University of Maryland. She has seen the forests filled with pine trees killed by the increasingly salty soil. When she started looking at maps, she said, \\"I realized that a lot of the land…was farms.” She started talking to farmers and asking if this was an issue on farms.","It was, but \\"a lot of people hadn't really been talking about it\\" outside their own communities, she said.","The United States Department of Agriculture gave Tully and other researchers $1.1 million to study the problem. She and her team hope to give farmers ways to stay on their land. She told VOA they are testing different crops on pieces of land around the Eastern Shore.","\\"Sorghum is my new favorite crop because it can grow without rain and it can grow with lots of rain. So this is actually a pretty, looks like a pretty good option.\\"","The grain crop may be a good choice to feed the nearly 600 million chickens raised in the area each year. As farmers know, chickens can deal with salt, dry weather conditions and heavy rains.","Tully's group is also testing other kinds of grain and a few crops that they believe can grow in the salt.","Yet just being able to grow a crop is not enough. The crop has to be profitable. So an economist on the team will be looking at the numbers.","But continuing to farm the land may not be the best plan of action. Some people believe the land should be given back to nature. They say the fields should be turned into wetlands, which are popular with duck hunters.","\\"There's money in duck hunting,\\" Tully said. Hunting organizations will pay farmers for a permit to hunt on their land. Farmers could earn a lot of money from duck hunters, she said.","Tully and her team are just getting started. It will be a few years before they really understand how to save the farms. They have proposals for what will help communities that have been farming this land for hundreds of years.","\\"There's a lot of history there. And as these seas rise, some of that history is going underwater.\\"","I’m Susan Shand."],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-08-talk-a","paperNumber":8,"kind":"talk","title":"AI-operated Robots Write Letters for Humans","date":"2024-03-29","sourceUrl":"https://learningenglish.voanews.com/a/ai-operated-robots-write-letters-for-humans-/7545989.html","publisher":"VOA Learning English","credit":"Julie Taboh reported on this story for VOA News. John Russell adapted it for VOA Learning English.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2024/03/27/01000000-0aff-0242-89c1-08dc4e8faa38.mp3","audioUrl":"/audio/mock-cet6-series/c6-08-talk-a.mp3","audioBytes":2135188,"publisherAudioBytes":2135188,"audioSha256":"085839bebfeba6caec2f3f3df29c12f3c4b070928ead66db57f3baa007a19a45","sourceSha256":"99792d3e7e980e7aa28d9c08eaa527184712c7c7d24e85eb77a43108159d4089","paragraphs":["Humans have been writing by hand for thousands of years.","Since ancient times, people have used every tool imaginable to share information, do business, and keep records.","But as computers took over the job and the type-written word became more common, something was lost in the process; namely, the charm and personal nature of a hand-written note or letter.","Modern tools","Now, letter writing is making a comeback in the form of artificial intelligence-operated robots. These AI robots can write notes for humans in their own handwriting.","David Wachs is the head and founder of Handwrytten. He said businesses use his company’s robots for handwritten letters and “thank-you” notes to create a strong and personal connection with those who receive them.","Many non-profit organizations also use handwritten letters to keep donations coming. It helps turn one-time givers, or donors, into yearly givers, Wachs explained.","Wachs added, “I think what's old is new again.”","A president’s hobby","Automated letter writing is not new. Thomas Jefferson, the third U.S. President, often used a polygraph created by British inventor John Isaac Hawkins. Jefferson considered the device the greatest invention of his time. It let him make copies of his letters to keep for his own records.","Charles Morrill is a historian and professional woodworker who worked as a guide for several years at Monticello, Jefferson’s Virginia home from 1770 until his death in 1826. Morrill said about the polygraph, “Jefferson falls in love with this and it becomes in many ways the hobby of his presidency...He keeps buying machines and exchanges ones that are not quite perfect for the next one that’s a little bit better.”","The president had more than ten of the devices at one point, Morrill added. Using what he considered wonderful technology, historians say Jefferson went on to write almost 20,000 letters in his lifetime.","In a January 15, 1809 letter to Charles Willson Peale, who worked with Hawkins to develop and perfect the machine, Jefferson wrote: “The use of the polygraph has spoiled me for the old copying press the copies of which are hardly ever legible ,” adding, “I could not, now therefore, live without the Polygraph.”","Morrill remembered that a visitor once told him, “What is it about you Americans and this new, new thing? Other cultures aren't like this. You Americans are just so absolutely convinced that the next new thing is going to do it; the latest software, the latest computer, the latest phone.”","“And I think this kind of begins with Jefferson,” Morrill added.","From early polygraphs to AI-created letters","Handwriting technology has greatly changed since Jefferson’s time.","Wachs says such technology now includes 3D printing and laser cutting, among others. And if users need help thinking of exactly what to write in their notes, they can choose AI to help them create a more effective message.","Whether via the printing press or the polygraph, a computer or a robot, one thing is clear… humans will use whatever tool they have to express themselves through the printed word.","I’m John Russell."],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-08-talk-b","paperNumber":8,"kind":"talk","title":"China Ban on Foreign Waste Creates Crisis for Recycling Businesses","date":"2018-06-13","sourceUrl":"https://learningenglish.voanews.com/a/china-ban-on-foreign-waste-creates-crisis-for-recycling-businesses/4435388.html","publisher":"VOA Learning English","credit":"VOA’S Mike O’Sullivan reported this story. Susan Shand adapted it for Learning English. George Grow edited this story.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2018/06/12/105a9355-412f-42a0-bc32-ffc43f4339be.mp3","audioUrl":"/audio/mock-cet6-series/c6-08-talk-b.mp3","audioBytes":3948162,"publisherAudioBytes":3948162,"audioSha256":"da5acaec5346bd23597afae25f70bf1489d43c38f791755883ae9be888a2b092","sourceSha256":"7ba851fb4b60486073a86f45194f71e6a090a27c9ca0e6aaabe3f1a49c2e24a1","paragraphs":["Just under $6 billion worth of American waste was sent to China last year to be remade into new products. Those products were then sent to the United States and other markets.","Waste recycling businesses have profited from low shipping costs for empty containers returning to China after the ships had unloaded their goods on the U.S. West Coast.","Today, very little waste is being shipped to China. The reason: China’s decision to ban many forms of foreign trash, from mixed papers to unwanted cloth. The ban went into effect on January 1.","The result of the measure can be seen at a recycling center in Anaheim, California. Its grounds are filled with 2,400 bales of mixed paper that the owners had planned to send to China.","The recycling center belongs to Republic Services, a company based in Phoenix, Arizona.","The unwanted paper is a result of an unusual 12-day backlog , notes James Castro, who heads the factory. No one knows where all that paper will go.","China’s government has banned imports of mixed paper, as well as some plastics, metals and other forms of waste. In April, the ban was expanded to include more metals and chemical waste. Those restrictions will go into effect later this year.","A ban on additional kinds of waste, including that from wood products, is being targeted for the end of 2019.","Less polluted waste","China has also set lower contamination levels for the waste it does accept. Now it accepts only 0.5 percent contaminants, down for most materials from 1.5 percent.","That has slowed the sorting process, said Richard Coupland, a vice president at Republic.","Additionally, the ban has led to a large drop in prices for recyclable goods, such as mixed paper.","One year ago, bales of mixed paper, like those stored outside the Anaheim recycling center, would have been worth $100 a ton. Today, each ton is worth \\"less than $5” or less than zero in some markets, Coupland noted. He added that much of the industry's backlog may end up in landfills.","North of Anaheim, in the city of Azusa, another Waste Management center also is dealing with changing rules for its workers and their sorting machines. They use magnets and other equipment to organize the waste. Now those systems do not meet the new levels and must be changed.","Adam Minter wrote a book called \\"Junkyard Planet: Travels in the Billion-Dollar Trash Trade.\\" He explains the problems facing recycling companies.","\\"Recycling is about manufacturing and if somebody doesn't want to use those raw materials,\\" then there is no reason for recycling programs.","He said that China's waste ban started as a desire to clean up the environment. But he added that nationalism and political control are also a part of the move.","'Shockwaves around the world'","Some environmentalists are happy about the waste ban.","Greenpeace East Asia plastic campaigner Liu Hua said it will send \\"shockwaves around the world.” He said it will force countries to examine their policies about waste, especially environmental contaminants like plastics.","Joshua Goldstein of the University of Southern California is an expert on China. He told VOA the ban may cause social problems there.","Goldstein has studied China’s 3 million to 5 million small recycling businesses. He says they make small amounts of money by sorting through trash and selling materials that can be reused.","\\"It also raised 3 to 5 million households out of poverty.\\"","Goldstein said China will find it difficult to create businesses as profitable as the small recyclers.","Companies are also looking for new markets. More recyclable waste from the United States will now go to India, Vietnam, Malaysia, Thailand or Indonesia. However, industry experts say shipping costs are high and demand in those countries is limited.","Because prices have dropped, there is hope for increased use for waste such as mixed paper in the United States.","Cleaning up waste","Brent Bell, vice president of recycling operations for Waste Management, said his company is trying to clean up its waste to meet the new levels China and other countries are demanding.","Bell said his company is working to educate Americans about cleaner recycling, adding it’s “something we all missed as an industry.\\"","\\"Whether we're shipping material to China, to India, or even to Louisiana, our customers all want to make sure the material is as clean as possible,\\" he said.","Republic's Coupland said the waste and recycling industry needs to work with communities to find a new business model to replace one that no longer works. This could make the cost of waste collection higher.","And China may change its policy again, noted Joshua Goldstein.","Paper waste is hard to replace, he says. China may be forced to change its bans if its manufacturers need raw materials.","The economics of the recycling industry are changing, he added.","I’m Susan Shand."],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-08-talk-c","paperNumber":8,"kind":"talk","title":"World’s Most Popular Dinosaur Gets New Look at Chicago Museum","date":"2019-01-05","sourceUrl":"https://learningenglish.voanews.com/a/world-most-popular-dinosaur-gets-new-look-chicago-museum/4725987.html","publisher":"VOA Learning English","credit":"Kane Farabaugh reported this story for the VOA News. Jonathan Evans adapted it for Learning English. Ashley Thompson was the editor.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2019/01/02/c37775e1-bffe-4a42-bc20-1cf58213b45b.mp3","audioUrl":"/audio/mock-cet6-series/c6-08-talk-c.mp3","audioBytes":1400910,"publisherAudioBytes":1400910,"audioSha256":"12f65129f7efa1d8128027b395d333c9d63b56254e4013de7f9a5453064b662a","sourceSha256":"369328ef2685cd5c54a092e99777b8a85ed7e3376c7bb2780b4ce08fa0854936","paragraphs":["In the early 1990s, scientist Sue Hendrickson discovered the world's largest Tyrannosaurus rex dinosaur skeleton. It was found in rock formations in the American state of South Dakota. The skeleton is known as Sue, in honor of Hendrickson.","Visitors to the Field Museum of Natural History in Chicago have been able to see Sue since 2000. However, for most of 2018, Sue was nowhere to be seen. Instead, experts spent 10 months working on and adding to the world-famous skeleton.","Jaap Hoogstraten is the Field Museum's director of exhibitions . He says museum workers have learned new things about the skeleton’s shape since 2000.","\\"Since 2000, we've made discoveries about the pose. We've added the gastralia, which are the belly ribs, which changes the outline of Sue quite a bit…”","The ribs themselves are not a new discovery. They have existed since the fossil was recovered. But scientists only recently understood how they fit onto the skeleton.","That understanding greatly changes what is known about the Tyrannosaurus rex.","Hilary Hansen is the Field Museum project manager.","\\"I didn't really realize that Sue weighed nine tons in real life. Really, adding this gastralia, these belly ribs, really changes the profile for Sue, and you can get a sense of how formidable and imposing it must have been to share an environment with this animal.\\"","Hansen adds that Sue's newly opened exhibit changes our understanding of the animal itself. It also helps show visitors Sue's natural environment and place in history.","\\"What we're trying to do is bring together everything about Sue that was all over the Field museum into one space so that our visitors can see this as a one-stop shop for all things Sue.\\"","The Field Museum usually welcomes over one million visitors a year. But Hansen expects that number to increase because of the new Sue exhibit. She said the museum is expecting up to 10,000 visitors each day in the first weeks of 2019.","I’m Jonathan Evans."],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-09-dialogue-a","paperNumber":9,"kind":"conversation","title":"Lesson 21: Trash to Treasure, Part 1","date":"2019-02-23","sourceUrl":"https://learningenglish.voanews.com/a/lets-learn-english-level-2-lesson-21/4273059.html","publisher":"VOA Learning English","credit":"VOA Learning English — Let’s Learn English Level 2 original intermediate teaching dialogue, including grammar instruction.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2018/03/06/fabffd67-3af1-480c-925c-0b87e11fe82b.mp3","audioUrl":"/audio/mock-cet6-series/c6-09-dialogue-a.mp3","audioBytes":1974164,"publisherAudioBytes":1974164,"audioSha256":"c7a35099e43eb045884c25f521039c45b71da5d3dfacbf5166a601ebc6fa3e26","sourceSha256":"d7d3fe600fc31217ea178ee0837ef5c67589ec54e92f256edda46593e242ba59","paragraphs":["Anna: (on phone, to Pete) Got it. Pete, I promise. I won’t tell anyone. (to herself) Bye. He is so strange .","Ashley: Hey, Anna!","Anna: Hi, Ashley!","Ashley: Are you talking to yourself again?","Anna: No, not this time. I was talking to Pete.","Ashley: How’s he doing?","Anna: Good. He has a birthday coming up! But he told me not to tell anyone.","Ashley: Why?","Anna: Well, from the way he was speaking , I don’t think he likes cake or presents or fun.","Ashley: That sounds like Pete.","Anna: Well, I don’t care. I’m getting him a present. Do you know where I can buy something unique ?","Ashley: I do -- Tanglewood Works. You will definitely find something unique there.","Anna: Great. I’ll go this weekend. Now, speaking of Pete’s birthday, what else should I do? I know. I’ll rent him a clown!","Ashley: Yeah, he’ll never speak to you again.","Professor Bot: Did you hear Ashley and Anna using the words talk and speak ?","Talk and speak both mean “to say words.” And, many times, you can use either word without losing any meaning. But there are some differences in when we use these words.","The word talk is usually used:","for conversations between two or more people","and informal situations, such as between friends or family","For example, Ashley asks Anna: “Are you talking to yourself again?”","Speak is usually used:","for one-way communication, such as presentations","formal situations , such as a boss speaking with her workers","to talk about language ability","and in polite requests","Keep watching, and listen for the words talk and speak .","(Anna goes to Tanglewood Works.)","Sue: Hey there. Welcome to Tanglewood Works! I’m Sue. How can I help you today?","Anna: Hi Sue, I’m Anna. A friend told me about your store. She said, “Anna, this place is really unique!”","Sue: We are! Here at Tanglewood Works, we focus on things that are handmade , reclaimed and recycled .","Anna: Wow! That is really good for the environment.","Sue: It’s good for you too. Local artists made all of these one-of-a-kind pieces. And I paint most of the furniture .","Anna: Can I look around?","Sue: Oh, please do.","(Anna walks around the store.)","Sue: So, Anna, do you like to make things?","Anna: Me? Oh, no. Every time I try to make something, something goes wrong.","(She knocks down many things.)","Anna: Oh, sorry. Sorry.","Sue: It’s okay. Anna, everybody can make something.","Anna: Sue, this piece is very interesting!","Sue: You know, when I found these pieces, they were broken and in a dumpster . But they spoke to me. And they said, “Save me, Sue! Save me!”","Anna: Sue, what do you mean they “spoke” to you?","Sue: When I see something special that someone has thrown away, I can almost hear it talk .","Anna: It’s not saying anything!","Sue: Anna, it’s not easy to see the treasure in trash .","Anna: Or hear it talk.","Sue: But you can learn. In fact, I teach private classes. And one is called Turning Trash to Treasure.","Sue: Next week, bring in some trash and we’ll turn it into treasure. Just remember – pick some trash that “ speaks ” to you.","Anna: Got it! I’ll see you next week!","Professor Bot: Will Anna find trash that “ speaks ” to her? What will it say? We’ll find out next week!"],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-09-dialogue-b","paperNumber":9,"kind":"conversation","title":"Lesson 22: Trash to Treasure, Part 2","date":"2019-03-04","sourceUrl":"https://learningenglish.voanews.com/a/lets-learn-english-level-2-lesson-22/4283017.html","publisher":"VOA Learning English","credit":"VOA Learning English — Let’s Learn English Level 2 original intermediate teaching dialogue, including grammar instruction.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2018/03/06/0fd0e840-fff7-4d90-aaeb-eba188526184.mp3","audioUrl":"/audio/mock-cet6-series/c6-09-dialogue-b.mp3","audioBytes":2302818,"publisherAudioBytes":2302818,"audioSha256":"b90e0765012579c589bd4f8876d01ea87565f8003396014e1d7236d1f29d5d66","sourceSha256":"0eb48719dcb58bde2442651923ec3bec2293a6eba5eecdc484a85d728f07009b","paragraphs":["Sue: Welcome to class, Anna. I can’t wait to see your trash!","Sue: Oh, okay. Alright, it’s a -- it’s a net with a … oh, it’s got a hole in it. Tell me about that.","Anna: This net said to me, “Anna, I used to catch stuff. I don’t anymore. So, use me, Anna.” That’s what it said . It said , “Use me, Anna.”","Sue: Okay. So...it’s a plastic helmet.","Anna: This plastic helmet said , “Anna. Hey, Anna, find me a head.”","Sue: Okay, um...and a broken toy.","Anna: This broken toy … this broken toy said to me – it said, “Anna, help me find fun.” “Help me, Anna” is what it said.","Sue: Anna, this stuff is not saying anything to you or me or anyone. It’s what we like to call in the business … garbage .","Anna: But you said to bring in trash.","Sue: Sometimes trash is treasure. Sometimes it's just trash.","Sue: Anna, don’t worry. Next week, I could teach you decoupage .","Anna: Decoupage. Decoupage. That’s fun to say.","Sue: All you need to bring is a clean shoe box. A box that held shoes.","Anna: I got it. I got it! See you next week!","Prof. Bot: Ut oh. It looks like Anna doesn’t know the difference between treasure and trash. She thinks those things are telling her something!","Prof. Bot: The words tell and say have similar meanings. But we use them in different ways.","Prof Bot: Tell means “to inform or instruct someone with words” and is almost always followed by an indirect object. For example, Sue says, “Tell me about that.”","Prof. Bot: The word me is the indirect object and tells us who is being told.","Prof. Bot: Say means “to express something with words” and focuses more on the words used. For example, Anna says, “That’s what it said. It said, ‘Use me, Anna.’”","Prof. Bot: Listen for when Anna and Sue use tell and say .","Sue: Anna, welcome to Decoupage class. Decoupage is just gluing pretty pictures onto stuff .","(Sue gets a phone call.)","Sue: Anna, I’ve got to talk to this person. I’ll be right back. Don’t start without me.","Anna: Got it.","(Sue leaves to take her phone call. Anna gets glue everywhere. She becomes covered with glue and paper .)","Anna: Okay. I can fix this.","Sue: Anna, what happened? I told you to wait for me!","Anna: Actually , you told me not to start without you, which I didn’t. Your glue is really sticky.","Sue: Next week, let’s try lamp making. There’s – there’s no glue. Here's a flier .","Anna: Thanks. See you next week.","Sue: Anna, you did really well this week. I think lamp making might be your thing !","Anna: Thanks, Sue. I did everything you told me to do.","Sue: Remember: I said to read the instructions really carefully. Where are those instructions?","Anna: Let’s just plug it in!","(Anna plugs in the lamp and, suddenly, the city loses electricity .)","Anna: So, what class will you be teaching next week?","Prof. Bot: Too bad Anna didn’t follow instructions! Visit our website for more on tell and say !"],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-09-passage-a","paperNumber":9,"kind":"passage","title":"Conservation Farming Means Healthy Soil and Profits","date":"2017-07-23","sourceUrl":"https://learningenglish.voanews.com/a/conservation-farming-means-healthy-soil-and-profits/3952152.html","publisher":"VOA Learning English","credit":"Steve Baragona wrote this story for VOA News. Anne Ball adapted this story for Learning English. Caty Weaver was the editor. We want to hear from you. Write to us in the Comments Section and visit us on our Facebook page .","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2017/07/20/84614ddc-6063-48d9-a03f-a81d935a00b4.mp3","audioUrl":"/audio/mock-cet6-series/c6-09-passage-a.mp3","audioBytes":2588318,"publisherAudioBytes":2588318,"audioSha256":"c8fda71ba30506680c89a2f93152f54d0d350702c18c3f7ed610432d7d848ef3","sourceSha256":"9324ebf7fdfd668c11917f3122db69a81f61335ea1b90e3f44630a2b6532fce6","paragraphs":["Agriculture experts have a message for farmers worldwide: Take care of your soil, and your soil will take care of you. By using the techniques of “ conservation agriculture”, they say farmers can save their land and save money, at the same time.","This is becoming more important as the world’s population grows. More people means more food needs to be grown to feed them.","Most modern agriculture looks like long rows of green crops covering large areas of land. They have neat rows of single kinds of plants with uncovered soil in between.","Trey Hill’s farm in the U.S. state of Maryland does not look anything like that. Instead, there are green plants mixed in with what is left from other plants. Together they cover the soil.","\\"If you don't like your fields to look like a mess -- It has to kind-of grow on you. Yet, I have a lot of other owners and peers that are, like, 'Wow, what you're doing is really exciting.'\\"","So, what is farmer Hill doing that is different? He is going against farming practices that are thousands of years old.","Most farmers around the world till their fields. That means they turn over and break up the soil before every planting. In modern times they use mechanical equipment to do the work.","In addition to tilling their fields, most farmers leave the soil bare, or uncovered, in the off-season. That is when they are not growing a crop. And many plant the same crop year after year.","All three of these methods can wear out the soil, however.","Some experts are backing the so-called conservation agriculture used by farmers like Hill.","David Montgomery is a professor of Earth and Space Sciences at the University of Washington in Seattle. His newest book is called Growing a Revolution . He spoke to VOA by Skype.","\\"These principles of conservation agriculture flip all three of those ideas on their head. So, it's a completely different philosophy to not till, to always have the ground covered with either a commercial crop or a cover crop , and to grow a much more diverse rotation .\\" Farmer Hill plants his crops into what is left of the crop before—without tilling the soil.","In the off-season he covers his fields with different crops. They hold onto the soil, and help prevent erosion, when water and wind remove soil.","The cover crop is not meant to be harvested. Instead, it feeds the soil. University of Maryland soil scientist Ray Weil says these fields will do better in times of extreme dryness.","\\"This kind of cover, whether it's standing or down here, is going to drastically increase the amount of rain that soaks into the soil.\\"","And, Hill says, this kind of farming is more profitable. Less tilling means using less fuel for his farm equipment. He buys less fertilizer – which are substances added to the soil-- because his cover crops feed the soil.","Hill, however is not an organic farmer. He kills his cover crops with chemicals.","But Weil says healthy soils do not have to be organic.","\\"These soils are full of life. And I bet you could go into even a certified organic field, if it's been tilled, you'll never find these things crawling around.\\"","Of course, this is not a perfect solution. Hill says some of these methods create new problems for him.","\\"Actually, this field was planted twice because slugs ate the beans the first time. Obviously, not very cost-effective. Seed's expensive. Planter's expensive. Diesel's expensive. So, it cost us a lot of money to learn. But we view it all as a learning process.\\"","Experts are working to help farmers in the developing world, as climate change and rising populations increasingly challenge the world's food growers.","I’m Anne Ball."],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-09-passage-b","paperNumber":9,"kind":"passage","title":"Trying to Make High-Tech, Low-Cost Farming a Reality","date":"2017-07-04","sourceUrl":"https://learningenglish.voanews.com/a/high-tech-low-cost-farming/3923469.html","publisher":"VOA Learning English","credit":"Steve Baragona wrote this story for VOA News. John Russell adapted his report for Learning English. George Grow was the editor.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2017/06/30/d72d879b-6f8f-49b4-bcb8-79fdd1dc2bbd.mp3","audioUrl":"/audio/mock-cet6-series/c6-09-passage-b.mp3","audioBytes":3741823,"publisherAudioBytes":3741823,"audioSha256":"bdd7e91adc21959b95cec47b12cef6bb63e6ae62ee3fb6fbfdc0130ad8344789","sourceSha256":"7e3355ec1f91942aaabc855bce43b91c0d580bebdc3de23958d520be8adc8c98","paragraphs":["Researchers are hoping to bring technology to small farms in developing countries.","Ranveer Chandra works for Microsoft Corporation, the American technology company. Chandra grew up in India. He remembers spending four months a year on his family's farm.","\\"There was no water,” he said. “No electricity. No toilets .”","Animals pulled plowing equipment through fields, as they have for centuries.","Now, Chandra – like many other researchers - wants to bring technology to small farms.","Their goal is this: to feed the world without destroying the planet.","What is precision farming?","Precision agriculture is a method of growing crops. Farmers use technology to collect very precise or exact measurements about their land. It tells farmers how they planted seeds, used fertilizers and chemical pesticides , and so on.","The main idea of precision farming, notes the Crop Society of America (CSA) , is that there are natural differences in the soil – even in the same field. Farmers who understand these differences are better able to produce crops.","Precision farming is fairly new in the United States, says the CSA. It began in the 1990s. At that time, Global Positioning System (GPS) technology became available to the public.","GPS technology is able to show your exact positions on earth.","GPS information can tell farmers where they planted seeds, used fertilizers, chemical pesticides, and so on.","Large scale and small scale farming","In many areas, farmers do not use high-tech equipment. Often in those places, crop production levels are low.","Now, high-tech tools are bringing a new level of precision to large-scale agriculture.","Farm equipment can plant different amounts of seeds and leave different amounts of fertilizer in different parts of a field. Water measuring equipment can tell farmers how much water their plants are getting.","Some of this technology is too costly for small farmers, especially in developing countries.","Artificial intelligence on the farm","Ranveer Chandra, the Microsoft researcher from India, is working to develop low-cost, high-tech tools for farmers.","Chandra developed a system that connects soil sensors to other sensing equipment through unused television (TV) channels .","These unused TV signals, known as \\"white space\\" frequencies, can provide broadband internet connection over long distances.","Some hospitals and schools in rural areas are already online with white-space connections, Chandra noted.","Each soil sensor provides information about conditions on the farm. To connect all the areas into a big picture, a drone aircraft takes photographs from high in the air.","Artificial intelligence (AI) compares these aerial photos to the sensor data. AI then can create maps of where the soil is too acidic or needs more water.","Similar technology can also help farmers watch their animals. Webcams can help farmers identify sick cattle, for example.","Fertile business","Chandra hopes to bring the cost of a simple system under $100. He notes the existence of low-cost replacements for the drones. A balloon tied to a mobile phone can serve the same purpose.","He added that Microsoft is considering different business models. Farmers could share a system, or a local farm business could rent systems to farmers.","Microsoft is just one company that sees agriculture as an area of growth for technology.","Google invested in a small company that gathers farmers' data on how different crops perform from farm to farm and year to year.","Many other companies are trying to enter the high-tech farm business, notes John Fulton of Ohio State University.","Fulton himself has helped develop a free phone app for farmers. The software program helps them compare different field management techniques.","\\"Everyone's trying to figure out how they play in agriculture,\\" he said. \\"We're really at an early stage of this digital agriculture revolution.\\"","Uncertain future","Demands on agriculture are increasing. As the world’s population grows, farmers will need to make more food without cutting down more forests or polluting the land and water.","To do that, existing farms need to produce more crops.","Chandra says that what farmers need is more information, so they can give the land what it needs.","\\"Like, apply water only where it is needed,” he said. Apply fertilizer only where it is needed. Apply pesticide only where it's needed.”","However, the level and speed at which new farming techniques and technologies will spread remains unclear.","Bruce Erickson is a precision farming expert at Purdue University in Indiana. He told the CSA that one problem faced by any new farming technology is getting people to use it with their existing methods.","Different countries have different farming methods and different ways of doing business.","\\"It takes people to implement new farming practices,\\" Erickson said.","I'm John Russell.","And I'm Caty Weaver."],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-09-talk-a","paperNumber":9,"kind":"talk","title":"Study Shows US Workplace Robots Doubled from 2009 to 2017","date":"2019-12-24","sourceUrl":"https://learningenglish.voanews.com/a/study-shows-us-workplace-robots-doubled-from-2009-to-2017/5204893.html","publisher":"VOA Learning English","credit":"Dora Mekouar reported this story for VOA News. Bryan Lynn adapted the report for Learning English. George Grow was the editor.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2019/12/16/9c4caadf-6603-47f5-8ebf-aea3e1c8d7c3.mp3","audioUrl":"/audio/mock-cet6-series/c6-09-talk-a.mp3","audioBytes":2013864,"publisherAudioBytes":2013864,"audioSha256":"34a200c053636082f9ad60e4feb47dec25ca5a88ebc29660695ea3ad37bfbaf0","sourceSha256":"c14aea86665406ad6c0ed7ab808c115b584dee0b99179e786a6274ce735b1da1","paragraphs":["A report says the number of robots being used in workplaces across the United States doubled from 2009 to 2017.","Most of the robots worked in manufacturing operations across America’s Midwest, the report said. It noted that the effect robots had on manufacturing job losses was lessened by economic growth that followed the last major U.S. recession.","The report comes from the Century Foundation research group, which is based in New York City.","William M. Rodgers III is a professor of public policy and chief economist at the Heldrich Center for Workforce Development at Rutgers University in New Jersey. He co-wrote the report. It examines how workplace robots are affecting U.S. workers and their pay.","“A growing economy independent of technology, independent of robotics, has been able to absorb , at least at the national level ... people who may have gotten displaced,” Rodgers told VOA.","Some Midwest states have twice as many robots as all other U.S. areas and have suffered from the rise in robot workers, the report found. Michigan, Ohio, Indiana, Illinois and Wisconsin have the highest levels of working robots, mostly in manufacturing businesses.","Industrial robots generally perform jobs that do not change much from day to day. These include putting things together, loading products, welding or painting.","The report found that the workers most affected by the machine takeover are young people. They also had less education than other workers. Black men and women experienced the greatest job losses.","Rodgers noted that U.S. workers who change jobs and find themselves employed in different industries often have to settle for lower pay. This can also be a problem when large job displacements lead to an oversupply of workers in some industries.","“If demand for workers is not growing fast enough, you begin to see a decline in wages,” he added.","Rodgers called on employers to develop better ways to help the displaced workers. If the right solutions are found, he said, some workers pushed out by robots can actually end up getting higher-paid positions. Assistance programs should include education and training programs to help prepare people for new career paths.","Rodgers added that now is the best time to prepare for the rise of the robots.","“What better time to be able to help people who are getting bullied , so to speak, by technology. Or getting bullied, so to speak, by globalization,” he said. “Times of prosperity is the best time... to invest in all Americans.”","I’m Bryan Lynn."],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-09-talk-b","paperNumber":9,"kind":"talk","title":"Much Publicized ‘Day Zero’ Changed Cape Town Forever","date":"2018-04-25","sourceUrl":"https://learningenglish.voanews.com/a/cape-town-day-zero-changed-city-forever/4364588.html","publisher":"VOA Learning English","credit":"Anita Powell reported this story for VOA News. Bryan Lynn adapted it for Learning English. Caty Weaver was the editor.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2018/04/25/d9ab8360-6845-4027-bf49-d4d8f9991a65.mp3","audioUrl":"/audio/mock-cet6-series/c6-09-talk-b.mp3","audioBytes":1807435,"publisherAudioBytes":1807435,"audioSha256":"f9a42ae23f6f17b00ff241397d1ab64369a1668f10cefb2227bb11d29a1bac61","sourceSha256":"c15dd9d557bf5945953b746155d45c5ac18f7d5ed15e13749c8a9d3f97d81495","paragraphs":["In January, officials in Cape Town, South Africa warned that the city’s usable water supply would be gone by April 21. The heavily-publicized date was called “Day Zero.”","The city on South Africa’s southwestern coast has been fighting the worst drought in a century. Cape Town is home to more than four million people.","Earlier this month, officials canceled the prediction for Day Zero. They now said it would not take place until 2019. The action came after drops in dam levels decreased and rainfall was expected to arrive in coming months.","Severe water restrictions remain in place for the city. Each Cape Town individual is limited to 50 liters of water each day. Officials have said the restrictions will continue until water supplies rise to acceptable levels.","The water crisis has left a lasting mark on Cape Town. The public has learned valuable lessons in water saving and administration.","Claire Pengelly works for Green Cape , a not-for-profit group that has advised city officials through the long drought. She said some people have praised the delay of Day Zero, saying efforts to deal with the drought have worked.","“We’ve been able to save, and it means that we will get through this summer,” she said.","However, Pengelly added, other people think they were tricked. They believe, she said, that Day Zero was a marketing campaign. Officials launched it, they argue, to get people to change behaviors although the city was never in real danger of complete water loss.","Pengelly said she thinks the threat of Day Zero turned out to be a good thing because it showed people the great need to conserve. She noted that even once the threat of Day Zero passed, overall water usage did not rise in Cape Town.","Deputy Mayor Ian Neilson has defended the city’s decision in January to declare April 21 would be Day Zero. He said at the time, water usage in the city was still at a very high level. Only after stronger restrictions were ordered did the situation turn around.","Claire Pengelly said she has learned to live with one-minute showers and other water-saving measures at home. But she also said she dreams of a day when she can once again take a long, hot bath – something she has not done in over a year.","I’m Bryan Lynn."],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-09-talk-c","paperNumber":9,"kind":"talk","title":"New Technology Harvests Energy from River and Tidal Movement","date":"2018-04-14","sourceUrl":"https://learningenglish.voanews.com/a/new-technology-harvests-energy-from-river-and-tidal-movements/4336066.html","publisher":"VOA Learning English","credit":"George Putic reported this story for VOAnews.com. Phil Dierking adapted it for VOA Learning English. Kelly Jean Kelly was the editor.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2018/04/06/823ab1e5-698d-4ea4-a13c-45a76feb9f04.mp3","audioUrl":"/audio/mock-cet6-series/c6-09-talk-c.mp3","audioBytes":1860815,"publisherAudioBytes":1860815,"audioSha256":"2d1ac4fa74f9fdd54209596f9d506ee8562c255d7780c3efbd089265434a41f1","sourceSha256":"ff311dfea21ad08a6613a2becf09f6627b180f174e8f4105b454ccf719fb76a2","paragraphs":["A number of companies have used the wind and sun to produce energy. Now, one company is using the force of flowing rivers and ocean currents.","The company is based in the U.S. state of Maine. It is called the Ocean Renewable Power Company, or ORPC. The company recently presented the new technology at an energy conference near Washington, DC.","Christopher Sauer is the chief executive officer and co-creator of ORPC. He says the technology was designed for small, rural communities that do not have easy access to power sources.","Taking energy from water movement","The ORPC technology is an energy generator which can be put under water, called RivGen. It works in a series of steps. First, the generator is put in the middle of a steel cage . The cage goes on top of a wide boat with a flat bottom called a pontoon. Wheels – or, turbines – are attached to each side of the generator.","Once the pontoon boat is fixed to one place, it is flooded with water. The pontoon, cage, and generator all sink to the bottom of the river. There, the river current turns the wheels and creates as much as 50 kilowatts of power.","CEO Christopher Sauer says the generator is not very tall, so it can work in water areas that are not very deep. Other companies are not able to work in shallow water, he adds.","And, Sauer says , the turbines are safe for the animals that live in the river.","\\"At the peak of salmon season, we had almost two million fish pass by this thing but at the end of all of that, we did not have a single fish injury that we knew about,” he said.","Sauer notes that another feature of the technology are “crossflow turbines . ” They permit the turbines to move in the same direction, no matter what way the water is flowing.","Sauer says the turbines’ shape permits the generator to harvest power from tidal currents in the ocean. The company’s ocean turbine is called TidGen. It can create up to 600 kilowatts of electricity, . enough to power a small settlement.","Right now, the amount of power TidGen can harvest changes as the strength of the tide goes up and down. But ORPC workers are trying to make the power output steady. In time, they want TidGen power to be part of the main energy grid .","CEO Christopher Sauer estimates ORPC’s current price is about 50 cents per kilowatt-hour. That price does not make the ORPC system competitive with natural gas. However, for small rural communities, diesel energy can cost more than $1 per hour. In these situations, energy from flowing water could be more economical.","I’m Phil Dierking."],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-10-dialogue-a","paperNumber":10,"kind":"conversation","title":"Lesson 24: I Feel Super!","date":"2019-03-16","sourceUrl":"https://learningenglish.voanews.com/a/lets-learn-english-level-2-lesson-24/4307612.html","publisher":"VOA Learning English","credit":"VOA Learning English — Let’s Learn English Level 2 original intermediate teaching dialogue, including grammar instruction.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2018/03/23/f1f4841a-c2cb-4ee3-9cbe-2a132ffb5c8e.mp3","audioUrl":"/audio/mock-cet6-series/c6-10-dialogue-a.mp3","audioBytes":2307833,"publisherAudioBytes":2307833,"audioSha256":"07b87997f49cacb0f96b59fdfdec4776c75d4d86cdd03d0efc3d3baea52331a2","sourceSha256":"63a5ec39ece9bcbeb9e7454720d40703fb52e1b7f96034ec4c3221f133aa4952","paragraphs":["ANNA: Hi! I see you like superhero culture. Me too.","ANNA: In fact, tonight I’m going to the big superhero convention. Are you going?","YOUNG MAN: Um, I don’t know.","ANNA: Well, you'd better decide soon. Last year, it sold out.","ANNA: So, since we’re talking about superheroes: would you rather become a superhero by accident, like Spiderman, or be born a superhero, like Wonder Woman?","ANNA: Take your time. It’s a big question. I thought about it for days –","YOUNG MAN: Okay. If I had to choose, I’ d rather be born a superhero.","ANNA: I’d rather become a superhero by an unexpected accident!","YOUNG MAN: Aren’t all accidents unexpected?","ANNA: Well, yeah.","YOUNG MAN: What was that!? Are you okay?","ANNA: I'm better than okay. I feel super !","PROF. BOT: Oh No! Anna was just hit by lightning. She had better get help.","PROF. BOT: We use had better to give advice. It is very informal and stronger than should and ought to . For example, Anna says: “ You'd better decide soon. Last year, it sold out.”","PROF. BOT: When we use had better , we usually shorten the word had for personal pronouns.","PROF. BOT: We use would rather to say what we or someone else prefers to do or have. For example, the boy says: “Okay. If I had to choose, I’d rather be born a superhero.","PROF. BOT: With would rather , we also shorten the word would when used with personal pronouns. Keep watching and listen for had better and would rather.","YOUNG MAN: You’d better see a doctor.","ANNA: I’ve never felt better!","YOUNG MAN: You were just struck by lightning !! And what happened to your hair and your clothes?","ANNA: I don't know. Wait, I do know. This is my super suit ! And this is my origin story .","YOUNG MAN: What are you talking about?","ANNA: An origin story tells the beginning of a superhero. You should know that.","YOUNG MAN: You're not making any sense , lady .","ANNA: I would rather be called Lightning Bolt Lady! It’ll sound great in a theme song: Lightning Bolt Lady!","ANNA: Now, I need to find my superpowers --","YOUNG MAN: Um, I really think --","ANNA: Wait. Don’t tell me. I’ll read your mind. You are thinking you’d like to be my super helper.","YOUNG MAN: I was not thinking that.","ANNA: ... that you’d like to live in a treehouse.","YOUNG MAN: No.","ANNA: … that you should eat more vegetables.","YOUNG MAN: Please, stop talking. You really should get some help.","ANNA: Mind reading is not my superpower. Maybe I can become invisible. I … am … invisible!","ANNA: You can’t see me. Who am I? I’m not here. You can’t see me.","YOUNG MAN: I can see you and so can everybody else.","ANNA: No power of invisibility. Maybe I can create a force field . I feel it working. Nothing can hurt –","(Someone throws a piece of paper and it hits her head.)","ANNA: Ow, that wasn’t very nice. I see I have a lot of work to do. Well, goodbye, non-super person!","YOUNG MAN: Wait. I’d better go with you. You might get worse…if that’s even possible.","ANNA: That's very nice of you, ordinary human . But I’ d rather go by myself. This is a quest.","YOUNG MAN: Every time you speak, I get more confused.","ANNA: A quest is a part of all superhero stories. You really need to work on your superhero studies. Now, stand back. I’ve never flown before.","YOUNG MAN: And you’re not flying now.","ANNA: Flying is also not my superpower. That’s too bad. It's going to be expensive to Uber everywhere. You know, I' d rather walk. It’s a nice day. Goodbye, non-super person.","YOUNG MAN: I am not talking to strangers again.","ANNOUNCER: Will Lightning Bolt Lady find her superpowers … ever? Ouch! Did that brick wall hurt? Will the young man ever talk to a stranger again?","ANNOUNCER: Find out on the next episode of Let’s Learn English!"],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-10-dialogue-b","paperNumber":10,"kind":"conversation","title":"Lesson 25: Only Human","date":"2019-03-24","sourceUrl":"https://learningenglish.voanews.com/a/lets-learn-english-level-2-lesson-25/4322773.html","publisher":"VOA Learning English","credit":"VOA Learning English — Let’s Learn English Level 2 original intermediate teaching dialogue, including grammar instruction.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2018/03/30/a591e14e-e65c-4370-91fb-06e8f9cad590.mp3","audioUrl":"/audio/mock-cet6-series/c6-10-dialogue-b.mp3","audioBytes":2285263,"publisherAudioBytes":2285263,"audioSha256":"0f30cb5ce6c6338db743bd29048f3eedb54664f6944bc81b15b30e278d98f51a","sourceSha256":"5689a4f80fa4a85c3d01092875704acf002d442ea7a25f6ddf88f938d23ab9ad","paragraphs":["ANNOUNCER: When last we saw Anna, she had made a new friend. And they had been talking about superheroes for a while when suddenly Anna became Lightning Bolt Lady!","ANNOUNCER: She tried to find her superpowers. But it did not go well.","ANNOUNCER: She can’t fly, become invisible or create a force field. And she really cannot walk through walls. Ouch, Lightning Bolt Lady.","ANNOUNCER: She had been walking into that wall for about 15 minutes when she had a great idea.","LIGHTNING BOLT LADY: I just had a great idea!","ANNOUNCER: I can’t wait to hear this one! But first, let’s talk about grammar.","ANNOUNCER: Professor Bot is on vacation this week. I’m the announcer. So, I’m going to tell you about the past perfect continuous.","ANNOUNCER: We use this verb tense to show that an action started in the past and continued to another time or action in the past.","ANNOUNCER: For example, I said, “She had been walking into that wall for about 15 minutes when she had a great idea.”","ANNOUNCER: Had been walking is the past perfect continuous of the verb walk . It’s had been plus the -ing form of the verb.","ANNOUNCER: You’ll hear me use this verb tense a few more times today.","ANNOUNCER: Now, what am I forgetting? Oh right! Lightning Bolt Lady’s great idea.","LIGHTNING BOLT LADY: If I want to know my superpowers, I’ll need to learn about lightning!","ANNOUNCER: So, she read many books about lightning.","LIGHTNING BOLT LADY: Wow. A lightning strike usually lasts less than a second .","(She tells this to a person and he slowly moves away.)","LIGHTNING BOLT LADY: Lightning is really fast and I like speed walking. So, maybe one of my superpowers is super-speed walking! (to stranger) Bye!","(She begins to super-speed walk.)","LIGHTNING BOLT LADY: Check! Super-speed walking is definitely one of my superpowers.","LIGHTNING BOLT LADY: Lightning has millions of volts of electricity . Amazing!","(She puts her hand up and lightning bolts shoot from her fingers.) LIGHTNING BOLT LADY: Wow! I can charge a lot of batteries with this superpower!","ANNOUNCER: She had been looking for hours for someone to help when she found her chance.","WOMAN: Hello? Hello? I’m sorry. I’m going to have to call you back. My phone is dying.","LIGHTNING BOLT LADY: Excuse me, I can charge your phone.","WOMAN: Really? Thanks!","LIGHTNING BOLT LADY: I’m Lightning Bolt Lady!","(She takes the woman's phone and shoots it with a lightning bolt. But it turns into ashes . Then, she gives the woman lots of money and smiles and says goodbye.)","ANNOUNCER: She had been practicing her superpowers all day. Suddenly, she heard a terrible sound – a child’s disappointment .","ANNOUNCER: These children tried to light a fire for over an hour. But then, they gave up .","PARENT: Hey kids, that wood will never burn. It’is too wet.","LIGHTNING BOLT LADY: Small humans, what is wrong?","CHILD: Stranger danger!","LIGHTNING BOLT LADY: I’m Lightning Bolt Lady!","YOUNG MAN: Oh no. It’s you.","LIGHTNING BOLT LADY: (to YOUNG MAN:) We meet again. And guess what: I found my superpowers.","CHILD: Well, we need a fire to toast the marshmallows to make S’mores .","LIGHTNING BOLT LADY: I can help.","YOUNG MAN: We don’t need a super-speed walker but thanks!","LIGHTNING BOLT LADY: Super-speed walking is just one of my superpowers. I can also do this!","(She tries to use her lightning bolts but it doesn't go well.)","LIGHTNING BOLT LADY: Sorry! Let me do it again.","(She lights the fire with her lightning bolts.)","CHILDREN: Thanks, Lightning Bolt Lady!","YOUNG MAN: Lightning Bolt Lady","LIGHTNING BOLT LADY: You’re welcome. But you don’t have enough firewood . Using my super-speed walking, I will get more.","(She super-speed walks around to get firewood.)","PARENT: Lightning Bolt Lady, come back! A lightning storm is coming!","LIGHTNING BOLT LADY: Not a chance ! There’s not a cloud in the …","CHILD: Lightning Bolt Lady, are you okay?","CHILD: Where's your super-suit?","ANNA: Oh no! I've lost my superpowers!","YOUNG MAN: It's starting to rain. Do you want to go inside and eat some S’mores?","ANNA: You read my mind.","ANNA: You know, I thought mind reading would be one of my superpowers. But it wasn’t.","CHILD: That’d be a cool superpower.","CHILD: But I’d rather be able to talk to animals."],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-10-passage-a","paperNumber":10,"kind":"passage","title":"Nigerian Entrepreneur Turning Plastic Waste into Usable Items","date":"2018-04-15","sourceUrl":"https://learningenglish.voanews.com/a/nigerian-entrepreneur-turning-plastic-waste-into-useable-items/4332664.html","publisher":"VOA Learning English","credit":"VOA’s Mariama Diallo reported on this story from Nairobi, Kenya. Xiaotong Zhou adapted it for Learning English. Caty Weaver was the editor.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2018/04/06/4a2a1069-3b67-4d3f-aad1-9b6120999557.mp3","audioUrl":"/audio/mock-cet6-series/c6-10-passage-a.mp3","audioBytes":1132616,"publisherAudioBytes":1132616,"audioSha256":"dc59f001c05257990f999d1f64fc27c6a5cf7592c21e3e5baac47ac6af29dc5f","sourceSha256":"5312211457ab351d146164b3284b67557d0c7e94300da8b4db175349924f9917","paragraphs":["Olayemi Samson is a Nigerian entrepreneur . He is turning plastic waste into useful things like clothing, school bags, car covers and shoes.","Samson says he is doing his part to fight pollution and support recycling while making a style statement.","A World Bank report says the city of Lagos makes about 9,000 metric tons of waste a day. Samson says part of that waste includes about 27 million plastic water bags.","“This waste, it takes takes 20 to 30 years before they decay. Where are they going to?”","Samson says that is when he came up with the idea of changing the waste into something useful.","The first step in Samson’s process is to collect the used bags from a dumpsite . Then, he washes them. After that, he can begin to sew the bags together, making car covers, school bags and other goods.","His latest recycled creation is a raincoat.","Some people cannot see past the history of Samson’s creations. Emmanuel Itiniyi of Lagos says the products are dirty.","He says, “I won’t allow my child to wear it as a cloth to go to school or a bag to go to school. It doesn’t make any sense.”","But others are more accepting, like Victor Anyaese.","“Yes I can use it because, seeing the picture, it looks lovely. But it depends on the kind of outfit I am using it for. But I can use it probably for leisure .”","Samson’s business is not profitable yet. But he hopes his work will help push young people and people in power to protect the environment.","I'm Jonathan Evans."],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-10-passage-b","paperNumber":10,"kind":"passage","title":"US-Russia Tensions, Not in Space","date":"2018-03-21","sourceUrl":"https://learningenglish.voanews.com/a/us-russia-tensions-not-in-space/4309089.html","publisher":"VOA Learning English","credit":"Steve Baragona reported this story for VOANews.com. Mario Ritter adapted the report for Learning English. George Grow was the editor.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2018/03/21/89c4a69e-8b3e-45eb-bdd1-b1e2ab4d69a1.mp3","audioUrl":"/audio/mock-cet6-series/c6-10-passage-b.mp3","audioBytes":2130287,"publisherAudioBytes":2130287,"audioSha256":"69fbe8aa2f237bd36675d7feb44645ee118ed1e5d99c43c4859e4c9813260cd1","sourceSha256":"01fc9bf6621c70d3636d13a64c7339f42cd0b0afdcf751ed7e06e08dd542ed56","paragraphs":["Two American astronauts and a Russian cosmonaut are on their way to the International Space Station (ISS).","The three were launched from the Baikonur space port in Kazakhstan on Wednesday.","The launch comes at a time of increased tensions between Russia and the United States. Yet experts note that the two sides continue working together in space.","Amy Shira Teitel is a space flight historian. She notes that NASA, the U.S. space agency, depends on Russia to reach the space station.","“Currently, Russia’s our only way up to orbit for the International Space Station and for any other human mission .\\"","Cathleen Lewis is with the Smithsonian Institution’s National Air and Space Museum in Washington. She works as a curator in the museum’s Space History Department.","Lewis says, since 2011, NASA has worked to develop its next generation of spacecraft. That means the space agency is depending on Russian cooperation.","“The Russians are partners in the International Space Station. Therefore, they were deemed reliable to be able to supply services to the space station. They have the Soyuz, which has been operational for 50 years now.”","Competitors cooperate even during Cold War","Cooperation in space between the two sides started in the 1970s during the Cold War. It was a period of intense competition between western countries and the Soviet Union.","But in 1975, an Apollo spacecraft linked up with a Soviet Soyuz spacecraft in Earth orbit. Cosmonauts and astronauts shook hands in space.","Lewis said that joint project was important.","“That created a bond , but also the knowledge that we could do this, even in the height of the Cold War, and probably one of the worse periods of the Cold War. That both sides could get together and do this, unperturbed by the politics going on around them.”","The “space race” between the United States and Russia ended in 1969 when NASA’s Apollo 11 brought two men to the moon.","However, space travel is dangerous and both the American and Soviet space programs suffered losses in their efforts to outdo each other in space.","The Apollo-Soyuz mission served to show that the two sides could work together in cooperation towards safety.","Currently, the U.S., Russia and 13 other countries cooperate to operate and supply the space station.","Future space missions will need even more cooperation because of the costs involved. Lewis said this model is likely to be important.","\\"It is going to take a lot of money, a lot of resources to ship there to make either the Moon or Mars habitable for humans. This will likely be the model in which humans explore our celestial neighbors in the solar system.\\"","Currently, cooperation remains the only way to get American astronauts to the ISS.","American companies SpaceX and Boeing, however, are expected to have spacecraft able to safely carry humans in coming years.","I’m Mario Ritter."],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-10-talk-a","paperNumber":10,"kind":"talk","title":"Coal-Rich Wyoming Has High Hopes for Carbon-Capturing Technology","date":"2019-09-22","sourceUrl":"https://learningenglish.voanews.com/a/coal-rich-wyoming-has-high-hopes-for-carbon-capturing-technology/5082886.html","publisher":"VOA Learning English","credit":"Steve Baragona reported this story for VOA News. Bryan Lynn adapted the report for VOA Learning English. George Grow was the editor.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2019/09/16/83fccee7-4c4c-4679-9f95-d7ed5ee0fb46.mp3","audioUrl":"/audio/mock-cet6-series/c6-10-talk-a.mp3","audioBytes":3061122,"publisherAudioBytes":3061122,"audioSha256":"d0e212d12e17dba5386d48e5d15148e62224e69254e25cd92e14fb96a864bdd0","sourceSha256":"77664d0047272bfda1ce32982bbab6f3b04afbd202470c50841a2c64ed2491c9","paragraphs":["Wyoming is, by far, the largest coal producing area in the United States. In 2017, mining operations across the state dug out more than 316 million tons of coal.","The town of Gillette, in the northeastern part of Wyoming, has a long history of coal mining. But in July, about 600 mine workers lost their jobs when the owner of two local mines went out of business.","Workers were shocked when the mines - two of the country’s largest – closed halfway through a workday with no warning.","Melissa Peterson Worden was one of those workers. “It is the thing they said would never happen,” she said about her job with the mining company Blackjewel. “And it happened.”","On the morning of July 1, Blackjewel sought bankruptcy protection in court. But when the company failed to get emergency financing to keep operating, the mines closed down later that day. They have not re-opened since.","Blackjewel’s bankruptcy is one example of the changes taking place in the U.S. electric power industry. Over the past 10 years, more than half of the nation’s 530 coal-fired power stations have closed or announced plans to do so. That information comes from an environmental group, The Sierra Club.","The reduction in coal power plants came as cleaner and less costly power technologies continued to increase.","The coal industry’s problems have also affected other parts of the country, including Appalachia. Appalachia gets its name from the Appalachian Mountains. It is considered the center of America’s coal industry.","The economic downturn has affected Wyoming less than Appalachia. One reason for this is because coal is very easy to mine in Wyoming’s Powder River Basin. In this area, huge pieces of coal sit just below the Earth’s surface.","Robert Godby is the director of the University of Wyoming’s Center for Energy Economics and Public Policy. He said companies with mines in the Powder River Basin were thought to be safe from a downturn because the businesses were so profitable.","“But that’s changed in a few short years,” Godby said. “The tide has just turned so quickly that it’s caught a lot of people off guard.”","Some coal industry supporters blame former U.S. President Barack Obama for pushing environmental rules that led to the closing of plants that had operated for years.","But industry experts say the problems facing coal-fired plants today have more to do with the rise in popularity of natural gas over the past 10 years. They note that gas costs less than coal.","In addition, the cost of solar and wind power in the past few years has helped renewable energy further cut into coal’s market.","One hope for the miners in Gillette is a project looking at ways to capture carbon dioxide produced by coal-fired power plants. Research has shown that rising levels of carbon dioxide in Earth’s atmosphere are one cause of higher temperatures.","Many experts think carbon capturing could be an effective way to fight climate change. If the process proves successful, it could really help the coal industry.","The experimental project, called the Integrated Test Center, is being carried out at a power plant just outside Gillette. There, researchers can directly connect equipment to the plant’s exhaust to test different ways to capture carbon dioxide.","However, the technology is still being developed and not expected to be widely available to power companies for several years.","Next year, the test center will be one of two areas taking place in the $20 million Carbon XPRIZE. The other area is in Alberta, Canada. Teams from around the world will compete to find the best way to turn the plant’s carbon dioxide emissions into profitable products, such as building materials or chemicals.","Whether they win or lose, local officials in Gillette say they hope some of the teams competing for the prize will set up operations there.","I’m Bryan Lynn."],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-10-talk-b","paperNumber":10,"kind":"talk","title":"Somalia’s Capital Struggles with Trash Problems","date":"2019-01-16","sourceUrl":"https://learningenglish.voanews.com/a/somalia-s-capital-struggles-with-trash-problems/4742345.html","publisher":"VOA Learning English","credit":"Harun Maruf reported this story for VOA News. Mario Ritter adapted it for VOA Learning English. George Grow was the editor.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2019/01/14/51775111-cbd2-48cf-8177-52563883ac41.mp3","audioUrl":"/audio/mock-cet6-series/c6-10-talk-b.mp3","audioBytes":2529839,"publisherAudioBytes":2529839,"audioSha256":"6b5b2a1832e8f58266520c0d6c60107bbe51b40eb0529ca5d1970f0ac111d12f","sourceSha256":"a9c917f2d99d4d69dbb7ffd794a081149ad720ec673f20f185576818e3443679","paragraphs":["Before the civil war in Somalia, the capital, Mogadishu, was known for its wide beaches , fresh sea air and pure blue ocean water.","Today, however, large amounts of trash are spreading everywhere.","Mogadishu is home to two million people. It produces about 2,500 tons of useless waste every day. But, until recently, it did not have an official place to put waste material or a trash recycling center.","Instead, people have been leaving trash on the streets, placing it along the coast or into the Indian Ocean.","VOA’s Somali Service recently reported on the problem. It found pictures of workers throwing trash into the water. Other pictures show huge amounts of cans, bottles, boxes, metal and other waste along the coastline.","Sometimes the trash burns, causing smoke and a bad smell to float into the city.","To deal with the problem, the Somali government officially announced the establishment of two waste landfills in December. One is in Mogadishu’s north. The other is in a community just south of the city.","But observers say more action is needed.","Hassan Nur teaches at Mogadishu’s Banadir University. He said there are no laws to prevent people from leaving trash all over the city.","“Waste management cannot work without legislation,” he said.","Trash harms the city’s health and environment","Parts of Mogadishu’s coastline remain free of trash. Somalis gather in these areas to enjoy the sea breeze and play in the warm water. The sights remind many people that, before years of civil war and terrorism, the city was once known as the Pearl of the Indian Ocean.","Mohamed Yahye is a Somali reporter. He told VOA he has seen all kinds of waste products left on Jazeera Beach. “I saw a tanker bring sewage waste and unload it onto the beach,” he said.","Nur said that the open dumping of waste can lead to increased risk of cancer and other diseases.","“It’s not just health problems. It also impacts on (the) environment – the air, the land,” he said.","Omar Abdullahi Hassan is commissioner of the Wadajir district, which includes Jazeera beach. He said it is now illegal to leave trash there.","Mohamud Yusuf Hassan is head of the Environmental Cleaning Company. It is one of three companies identified by police as unloading trash on beaches. Police have yet to arrest anyone for doing so, however.","Hassan said his company, which employs over 300 people, is now listening to police. “We don’t dump into the sea now,” he said.","But his company is having trouble finding places to leave waste materials or to recycle trash. “There is no place to manage it,” he said.","Hassan agreed that laws are needed to help control the problem.","The commissioner of Wadajir said his group has been working in recent weeks to get the large, new landfills into operation. He added that it is wrong to put trash on the beaches.","“Beaches are the most beautiful parts of this country,” he said.","I’m Mario Ritter Jr."],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"},{"id":"c6-10-talk-c","paperNumber":10,"kind":"talk","title":"Teaching Children How to Ride Bicycles","date":"2019-05-08","sourceUrl":"https://learningenglish.voanews.com/a/teaching-children-how-to-ride-bicycles/4899700.html","publisher":"VOA Learning English","credit":"VOA reporter Faiza Elmasry reported this story. Hai Do adapted it for Learning English. Caty Weaver was the editor.","termsUrl":"https://learningenglish.voanews.com/p/6861.html","license":"Original VOA text/MP3 reuse with credit, including commercial use; third-party material excluded; independent audio-rights review pending.","originalAudioUrl":"https://voa-audio.voanews.eu/vle/2019/05/03/737999b3-7666-4ea0-b92b-bdd1f9bea9ff.mp3","audioUrl":"/audio/mock-cet6-series/c6-10-talk-c.mp3","audioBytes":2345534,"publisherAudioBytes":2345534,"audioSha256":"f0b0135a30e17b5557746b6fc9a95e990e2f50b2e8bb6ca4a660147763261c5d","sourceSha256":"fc5ec8be6c832405b805aa5cb1f7b01328850ebd786772f8ddaa8ff490daee1b","paragraphs":["On a sunny, spring day, a group of children, four to seven-years-old, sit on their bicycles. They wear helmets to protect their heads and gloves to protect their hands. Their mothers, standing nearby, watch them closely.","The children are ready to learn how to ride.","Rachel Varn still remembers how she felt riding a bicycle for the first time. She says, “It’s probably the biggest confidence booster . It gives kids such a sense of independence and agency.”","Now, her job is helping children experience that moment.","Basics of biking","Rachel Varn left her job of selling bicycles to become a trainer for bicycle riding last year. She founded Pedal Power Kids to teach bicycle education.","Before starting a ride, she teaches the children how to make sure the bicycles are in good condition for safe use. She calls it “the ABC quick check.”","“A” is for air, she explains. “We have to check our tires before we ride. B is for brakes . We want to make sure our brakes work before we find ourselves on the top of a hill about to go down. And C is for chain .”","She says the chain must be clean.","The rest of the training is more fun. The children learn riding skills, from balance and pedaling to turning, starting and stopping. And they learn to keep their eyes up and look ahead while riding.","Varn says many children struggle to do this. They look down at the pedals instead.","She adds, “Obviously that doesn’t allow them to see what’s going on around them, and it also doesn’t allow them to turn properly. ”","Varn says watching where you are going helps you turn easier.","Biking changes lives","Learning to ride a bicycle can open a whole new world to children. It gives them a sense of accomplishment and freedom. They become more sensitive to their surroundings and better able to make safe, smart decisions going from one place to another.","Varn’s goal is to get more children on two wheels. She says, “That’s really a great way for kids to be active and develop healthy habits. It helps reduce pollution and just keep families and communities connected.”","Since starting Pedal Power Kids last year, Varn has helped around 250 new riders.","Julia Roeling had neither the time nor the confidence to teach her children how to ride. She signed up two of her three children in Van’s bicycling class.","Varn gets the kids moving, Roeling says.","“Now, they can do it safely. And they know how to get around the community and stop at the stop signs and be together on their bikes.”","Roeling says riding bicycles is a great activity for children. They spend the time outside instead of playing video games all day.","The children in the classes are happy and excited about their experiences. They have fun riding with their friends. They give names to their bikes. And they enjoy doing the ABC quick check for safety.","Varn observes, “We probably wouldn’t be playing lacrosse when we're 75 or 89, but we certainly can be riding a bike!”","I’m Jonathan Evans."],"importedAt":"2026-10-24","reviewStatus":"source screened; question matching, independent content review and third-party audio review required"}]`);function e(a,n,i,r,h,u){const d=c.find(o=>o.id===a);if(!d)throw Error(`Missing CET6 source ${a}`);const p=h.map(o=>{const s=d.paragraphs.find(l=>l.includes(o));if(!s)throw Error(`Missing CET6 evidence ${a}/${n}/${o}`);return s}).filter((o,s,l)=>l.indexOf(o)===s).join(`

`);return{number:n,prompt:i,options:r,answer:0,evidence:p,explanation:u}}function t(a,n,i,r,h){return{sourceId:a,section:n,label:i,summary:r,questions:h}}const m={number:8,theme:"证据、公共资源与技术的新用途",recordings:[t("c6-08-dialogue-a","conversation","长对话1","面粉宝宝实验结束后，主管根据执行过程而非报告厚度评价两位员工。原录音保留反身代词教学。",[e("c6-08-dialogue-a",1,"How does Anna explain her exhausted appearance at the meeting?",["She has taken the flour baby everywhere and fed it every three hours.","She has spent the night writing a binder full of research.","She has been preparing first-aid lessons for the whole team.","She has stayed awake to bake a new batch of cookies each hour."],["I took her everywhere"],"Anna 直接把疲惫归因于随身带着面粉宝宝、每三小时喂一次。厚重研究夹属于 Pete；急救是事故后的处理，不是整夜授课；她说饼干是当早制作，并非每小时烤一批。"),e("c6-08-dialogue-a",2,"What sequence does Anna give to explain the burn on the flour baby?",["It fell into the sink and caught fire when she tried to dry it.","It was cut while she made salad and burned during first aid.","It caught fire beside the dinner and was cooled in the sink.","It burned while baking cookies and was then placed in a microwave."],["knocked her into the sink"],"Anna 说宝宝先掉进水槽，她用微波炉烘干时起火。做沙拉时刀割是另一次事故；录音没有说先在晚餐旁烧着再放水槽，也没有把烤饼干说成烧伤原因。"),e("c6-08-dialogue-a",3,"Why does Ms. Weaver praise Anna despite Pete’s objections?",["Anna followed the instructions for the experiment.","Anna submitted more research pages than Pete did.","Anna avoided the accidents that Pete had reported.","Anna taught Pete how to use reflexive pronouns."],["she followed instructions","only did one page"],"主管回应“她遵守了要求”，评价依据是执行任务。Pete 指出 Anna 只有一页且弄湿了；事故确实存在；代词说明是 Professor Bot 的教学，不是 Anna 教 Pete。"),e("c6-08-dialogue-a",4,"How does Anna defend using the flour to make food?",["She made it at the end of the experiment, when it was just flour again.","She had been instructed to bake it before submitting her research.","She needed to reduce its weight before Ms. Weaver examined it.","She believed baking was the first-aid treatment required by the task."],["at the end of the experiment"],"Anna 强调是在实验结束时制作，那时它只是面粉。她没有说主管要求先烤后交，也未以减重或急救来辩解；这些把先后顺序、主管观察和事故处理混在一起。")]),t("c6-08-dialogue-b","conversation","长对话2","Anna、Penelope 和 Rick 采访车展，拍摄试驾时对“素材是否足够”产生分歧。保留直接与间接引语教学。",[e("c6-08-dialogue-b",5,"What does Anna report as Ms. Weaver’s instructions for the car-show story?",["Show many cars, interview people, and have fun.","Film the robot, select a winner, and interview drivers.","Compare driving courses, record a race, and get lunch.","Show classic cars, discuss prices, and test each model."],["show lots of cars"],"Anna 复述的三项是展示许多汽车、采访人们、玩得开心。机器人和试驾是现场后来出现的内容；评奖、价格比较、逐辆测试和午餐都不是这组三项指示。"),e("c6-08-dialogue-b",6,"What common ground does Anna identify among the people interviewed?",["Their opinions differed, but they shared a love of cars.","Their preferred cars differed, but they all praised the robot.","Their jobs differed, but they all wanted to drive the Jaguar.","Their driving experience differed, but they favoured the smooth course."],["very different opinions"],"Anna 说受访者意见不同，但都喜欢汽车。机器人、Jaguar、平整赛道虽然随后出现，却没有被说成所有受访者的共同评价或愿望。"),e("c6-08-dialogue-b",7,"How does Anna describe the difference in her driving permissions on the two courses?",["She cannot drive on the smooth course but can drive on the uneven one.","She can drive on the smooth course but must leave the uneven one to a driver.","She can drive on both courses after completing the interviews.","She cannot drive either course until the robot demonstration ends."],["This course is smooth","I can’t drive, unfortunately","I could drive this course"],"前一条平整赛道处 Anna 说自己不能开；后一条颠簸不平赛道处说获准驾驶。不能根据平整程度推断许可，也不能把采访完成或机器人表演当作许可条件。"),e("c6-08-dialogue-b",8,"What is the disagreement near the end of the car-show visit?",["Penelope thinks they have enough footage, while Anna wants another ride.","Penelope wants more interviews, while Anna wants to stop for lunch.","Penelope wants the smooth course, while Anna insists on filming the robot.","Penelope thinks the video failed, while Anna wants to replace the camera."],["enough test drive video","Ms. Weaver said to get a lot","want to get lunch"],"Penelope 说试驾视频已经够了并想吃午饭，Anna 却借主管“多拍点”的话继续乘车。不是 Penelope 要更多采访，也没有设备故障或更换相机的问题。")]),t("c6-08-passage-a","passage","听力篇章1","公众用 iNaturalist 记录物种，为保护管理和科研提供地点、时间及鉴定信息。数据为原报道时期的记录。",[e("c6-08-passage-a",9,"Why does Abugattas consider a record of local species necessary?",["It establishes what is present so protection efforts can be judged.","It identifies which volunteers should become professional scientists.","It determines which photographs should be sold to researchers.","It replaces the need to study changes caused by development."],["protect something","gauge of how good"],"“先知道有什么才能保护”，再比较出现或消失的物种，才可评估管理成效。记录不是人才选拔或售图程序；它帮助研究开发带来的变化，而非取消这项研究。"),e("c6-08-passage-a",10,"What does iNaturalist record that helps experts map changes in wildlife?",["The location and time associated with each photograph.","The training history of each person uploading a photograph.","The cost and age of the phone used for each observation.","The number of researchers who have visited each park."],["where and when the picture"],"录音明确说记录照片拍摄的地点与时间，因此可建立分布及变化地图。志愿者经历、手机价格年龄、研究者到访数量不是这里说明的制图数据。"),e("c6-08-passage-a",11,"How does the report describe cooperation through the program?",["Users help identify images, while their observations support scientific studies.","Experts train each observer before images can be added to the program.","Local officials select one species for all observers to photograph each week.","Researchers replace public observations with photographs from their own surveys."],["try to help identify","help professional scientists gather data","used in studies"],"公众上传后，全球用户可以协助鉴定，汇总观察已用于科研。录音未设置先培训、统一周目标的条件，也没有说专业人员用自己的照片替换公众记录。")]),t("c6-08-passage-b","passage","听力篇章2","海水侵入威胁历史农田，研究团队比较耐受作物、经济收益与改为湿地等路径；不把报道预测当作当前结论。",[e("c6-08-passage-b",12,"What process is making farmland near Chesapeake Bay harder to cultivate?",["Rising seas bring salt water inland, adding to the effects of sinking land.","Rising rainfall carries fresh water away while the land becomes higher.","Expanding grain farms remove the trees that normally lower soil salinity.","Increasing duck hunting prevents farmers from draining their fields."],["land around the Chesapeake Bay"],"该段说明土地长期下沉，海平面上升又使盐水进入河道，土壤过咸。不是土地抬升，也未把种粮、砍树或猎鸭说成土壤盐化原因。"),e("c6-08-passage-b",13,"Why does Tully describe sorghum as a promising crop in her trials?",["It can grow with either very little rain or a great deal of rain.","It produces a profitable harvest before the team measures soil conditions.","It removes salt from surrounding waterways as it grows.","It can be grown without replacing the existing pine forests."],["Sorghum is my new favorite"],"Tully 的原话是少雨、多雨都能生长，这是她此处给的理由。录音随后仍要求计算盈利；未宣称高粱脱盐，也没有说保留松林就是试种优势。"),e("c6-08-passage-b",14,"Why is an economist included in the research team?",["A crop that survives still has to provide a financial return.","The team must decide how much salt a chicken can tolerate.","The farms must first prove that their ownership dates are correct.","The researchers need permission to move the coastline inland."],["crop has to be profitable"],"能长出来不等于值得种，经济学家要核算收益。耐受性属于农学问题；产权年代只是历史背景，移动海岸也不是经济学家的任务。"),e("c6-08-passage-b",15,"What alternative source of income is discussed if some fields become wetlands?",["Selling hunting permits to groups interested in ducks.","Charging researchers to remove the dead pine trees.","Selling the farmland to the Department of Agriculture.","Moving the chicken farms to newly built coastal land."],["fields should be turned into wetlands","pay farmers for a permit"],"湿地能吸引鸭类，狩猎组织可付费获得进入农地猎鸭的许可。研究经费不等于购买农场；清树收费、填海新地上的鸡场均不是这条备选收益路径。")]),t("c6-08-talk-a","talk","报告与讲解1","从 Jefferson 的复写机器到 AI 手写机器人，报道讨论技术如何服务个性化通信。保留原采访与历史引文。",[e("c6-08-talk-a",16,"Why do businesses use Handwrytten’s robots, according to Wachs?",["To create a more personal connection through handwritten notes.","To preserve exact copies of letters in presidential archives.","To reduce the need to send follow-up messages to customers.","To replace thank-you notes with machine-printed account records."],["businesses use his company"],"Wachs 说手写信和感谢卡能建立亲切、个人化的关系。留副本是 Jefferson 的用途；录音没有说免去后续沟通，亦不是改成机器打印账单。"),e("c6-08-talk-a",17,"What did the polygraph allow Jefferson to do?",["Keep copies of letters while writing them.","Send letters without relying on a delivery service.","Turn illegible letters into newly printed type.","Ask a machine to choose the wording of a reply."],["It let him make copies"],"这里的 polygraph 是复写装置，让 Jefferson 保留自己书信的副本，不是测谎仪或邮递系统。AI 帮助组织措辞是现代部分；旧压印副本难辨认并不意味着机器负责把来信转成铅字。"),e("c6-08-talk-a",18,"What links the historical and modern examples in the report’s conclusion?",["People adapt available tools to communicate through writing.","New handwriting machines make earlier copying methods more accurate.","Presidential collecting habits determine business communication trends.","The main aim of writing technology is to reduce the amount people write."],["Whether via the printing press"],"结尾把印刷机、复写器、电脑和机器人并列，归纳人们借工具以文字表达。没有说新机器改良旧压印法、总统收藏决定企业潮流，或这些技术旨在让人少写。")]),t("c6-08-talk-b","talk","报告与讲解2","2018 年贸易限制改变回收行业的成本、去向与清洁标准；题目仅依据历史报道，不作现行政策说明。",[e("c6-08-talk-b",19,"What had made shipping American recyclable waste to China economical?",["Empty containers could carry it back at low shipping costs.","Manufacturers paid the shipping costs before products left China.","Recycling centres owned the ships unloading on the West Coast.","Foreign governments covered the cost of sorting mixed paper."],["low shipping costs for empty"],"原先运抵美国西岸的货柜返程空置，返运废料成本低。不是制造商预付运费、回收厂自有货船，亦未提外国政府承担分拣费。"),e("c6-08-talk-b",20,"Why does the report say the sorting process has slowed?",["Accepted waste must meet a stricter contamination limit.","More containers are carrying finished goods to the West Coast.","Mixed paper now sells at a higher price in foreign markets.","New buyers require the same material to be sorted in China."],["0.5 percent contaminants","slowed the sorting process"],"接受的废料杂质比例从多数材料原来的 1.5% 降到 0.5%，更严标准拖慢分拣。货柜背景不是直接原因；纸价在下降，录音也未要求必须送中国再分拣。"),e("c6-08-talk-b",21,"What limits the usefulness of finding alternative overseas buyers?",["Shipping is costly and demand in those markets is limited.","The new buyers require companies to keep mixed paper in California.","American manufacturers have already bought the entire backlog.","The alternative markets have banned the same materials on identical terms."],["shipping costs are high and demand"],"录音列出替代市场后马上指出运输费用高、需求有限。它没有说这些买家要求纸留在加州、美国厂商已买光积压，或各国以完全相同条件禁运。")]),t("c6-08-talk-c","talk","报告与讲解3","芝加哥 Field Museum 根据对已发现骨骼的新理解重塑 Sue，更新外形与展览叙事。时间均为原报道背景。",[e("c6-08-talk-c",22,"Why was Sue absent from public view for much of 2018?",["Experts were working on and adding to the skeleton.","The fossil had returned to South Dakota for excavation.","The museum was lending the skeleton to several other museums.","Researchers were searching for the person who first discovered it."],["spent 10 months working"],"报道说专家用十个月调整、补充骨架。南达科他是最初发现地点，Hendrickson 是发现者；录音未说回去挖掘、巡展或寻找发现者。"),e("c6-08-talk-c",23,"What was new about the belly ribs added to Sue?",["Scientists had newly understood how existing bones fitted the skeleton.","Scientists had just recovered those bones from a different fossil site.","The museum had replaced missing bones with parts from another dinosaur.","The ribs had been removed because they changed the pose incorrectly."],["ribs themselves are not a new discovery","how they fit"],"腹肋骨自发掘时已存在，新的进展是理解安装关系。不是另挖到新骨骼，也没有移植另一恐龙骨骼或因姿态错误移除的说法。"),e("c6-08-talk-c",24,"According to Hansen, what does adding the belly ribs help visitors appreciate?",["How massive and imposing the living animal must have been.","How long the original excavation took in South Dakota.","Why the museum chose to name the skeleton after its discoverer.","Why dinosaur bones can remain preserved for so many years."],["weighed nine tons"],"Hansen 把腹肋骨、九吨体重与强大的体态联系起来，帮助想象活体的压迫感。发掘时长、命名缘由和化石保存机制不是这段说明的作用。"),e("c6-08-talk-c",25,"What is the purpose of bringing material about Sue into one exhibition space?",["To connect information about the animal, its environment and its history.","To move research away from the museum and concentrate on ticket sales.","To keep visitors from comparing earlier and current versions of the skeleton.","To replace the natural-history collection with a display of excavation tools."],["natural environment and place in history","one-stop shop"],"展览整合分散在馆内的 Sue 信息，同时呈现其自然环境和历史位置。没有取消研究、阻止版本比较，或用挖掘工具代替自然史馆藏的计划。")])]},f={number:9,theme:"循环利用、资源精配与转型成本",recordings:[t("c6-09-dialogue-a","conversation","长对话1","Anna 为 Pete 挑选特别的生日礼物，走进把废弃物改成作品的商店。保留 talk 与 speak 的教学插话。",[e("c6-09-dialogue-a",1,"What leads Anna to ask Ashley about a place selling unusual items?",["She wants to buy Pete a birthday present.","She wants to replace furniture damaged at work.","She needs materials for a class she is teaching.","She is looking for a store that can repair a telephone."],["He has a birthday coming up","getting him a present","Tanglewood Works"],"Anna 知道 Pete 生日将近，虽他不愿公开，她仍想买一件独特礼物。家具、课程都在后续商店对话中出现，但不是她询问 Ashley 的起因；修电话并未提出。"),e("c6-09-dialogue-a",2,"What distinguishes the items at Tanglewood Works, according to Sue?",["They are handmade or reused pieces created by local artists.","They are factory-made pieces selected to match customers’ homes.","They are furniture pieces rented from nearby artists for birthdays.","They are new pieces sold with free private painting lessons."],["handmade , reclaimed","Local artists made"],"Sue 介绍手作、回收、再利用的特色，并说独件作品出自本地艺术家。她虽自己漆家具，但未说工厂量产、生日租赁，或购买新家具附免费课。"),e("c6-09-dialogue-a",3,"What does Sue mean when she says discarded pieces “spoke” to her?",["She could sense something special worth saving in them.","She could remember the artists explaining their original designs.","She could hear a customer asking her to repair those same pieces.","She could recognise instructions left by the previous owners."],["something special that someone has thrown away","see the treasure in trash"],"Sue 用拟人表达自己看出了废品的特殊价值，想把它们救回来；并非真有声音，也不是听到艺术家、顾客或旧主留下的说明。Anna 对字面意义的误解正是笑点。"),e("c6-09-dialogue-a",4,"What does Sue ask Anna to do for their next meeting?",["Bring discarded material she finds inspiring to a private class.","Choose a finished birthday present and return it for repainting.","Bring Pete to the shop to help identify his favourite furniture.","Prepare a presentation explaining the difference between talk and speak."],["teach private classes","Next week, bring in some trash"],"Sue 让她下周带能引起自己兴趣的废品来做“变废为宝”。不是把买好的礼物返工，也没要求带 Pete；语言区别由 Professor Bot 讲解，未变成 Sue 给的作业。")]),t("c6-09-dialogue-b","conversation","长对话2","手作课程里，Anna 对“有价值的废品”和操作指令的理解屡出偏差。保留 tell 与 say 的讲解，不依赖无声画面出题。",[e("c6-09-dialogue-b",5,"How does Sue respond to the net, helmet and toy Anna brings?",["She says these particular objects are garbage rather than useful treasure.","She says the objects are useful but too clean for the planned project.","She asks Anna to repair each object before describing it.","She decides to sell the objects together in her furniture shop."],["this stuff is not saying anything","Sometimes trash is treasure"],"Sue 区分“有时废品是宝，有时只是垃圾”，认为这批东西属于后者。不是太干净；也没有提出先修复再介绍或打包出售的决定。"),e("c6-09-dialogue-b",6,"What material does Sue ask Anna to bring for decoupage?",["A clean box that previously held shoes.","A plastic helmet with a smooth surface.","A repaired net that can support pictures.","A broken toy that has been covered in paper."],["bring is a clean shoe box"],"下一堂拼贴装饰课只要求干净鞋盒；头盔、网、坏玩具属于上一批失败材料。题目限定 Sue 的准备要求，不是推想哪些物品也可能做手工。"),e("c6-09-dialogue-b",7,"What distinction does Anna make when Sue says she told her to wait?",["Sue had said not to start without her, rather than explicitly telling her to wait.","Sue had asked her to leave the class, rather than to stay beside the table.","Sue had told her to read the instructions, rather than to answer the telephone.","Sue had said to practise lamp making, rather than to work with glue."],["I told you to wait","you told me not to start without you"],"Anna 按措辞辩解：Sue 原话是“我不在不要开始”，她声称自己没开始，而不是承认收到明确“等我”命令。电话是 Sue 接的；读说明和灯制作是之后的课程，不能调换顺序。"),e("c6-09-dialogue-b",8,"What does Sue remind Anna to do before the lamp is plugged in?",["Read the instructions very carefully.","Add more glue to the lamp’s paper covering.","Return to the class about damaged toys.","Find a clean shoe box to hold the electrical parts."],["read the instructions really carefully"],"灯制作阶段 Sue 提醒仔细阅读说明并问说明在哪里，Anna 却急着插电。胶和鞋盒属于拼贴课；损坏玩具是早先的选材，不是此时的安全步骤。")]),t("c6-09-passage-a","passage","听力篇章1","保育农业把少耕、持续覆盖、轮作结合起来，也面对害虫和试错成本。非实时农业操作建议。",[e("c6-09-passage-a",9,"Which combination describes the conservation approach discussed by Montgomery?",["Less soil disturbance, continued ground cover, and more varied crop rotation.","Frequent tilling, bare soil between seasons, and a stable single crop.","Organic certification, fewer crop varieties, and longer periods without planting.","Deeper plowing, removal of crop remains, and more chemical fertilizer."],["principles of conservation agriculture"],"Montgomery 把少耕、地表持续覆盖、多样轮作并列。频繁耕作、空季裸土、连种单作物恰是被反转的传统；该方法也不以有机认证为前提。"),e("c6-09-passage-a",10,"Why does Hill say the method can improve profitability?",["Less tilling saves fuel, and cover crops reduce purchased fertilizer needs.","Extra tilling lowers seed costs, and organic labels raise selling prices.","Uncovered fields need less equipment, and farmers can sell the cover crop.","Repeated bean planting prevents losses, and chemicals are no longer used."],["Less tilling means using less fuel"],"收益理由是少翻土节油、覆盖作物养土而少买肥料。录音说明覆盖作物不是拿来收获，Hill 仍用化学品；豆被蛞蝓吃掉后的重播反而增成本。"),e("c6-09-passage-a",11,"What does the example of planting the bean field twice show?",["The approach can introduce costly problems even when it offers benefits.","The cover crops are intended to produce two commercial harvests.","The soil needs more tilling before conservation methods can begin.","Organic certification prevents farmers from controlling new pests."],["field was planted twice","not a perfect solution"],"蛞蝓吃掉第一批豆，重播花费种子、机具和燃料，说明仍有新问题和学习成本。不是两次计划性收获；报道未把事故归为有机认证限制或未耕地的必然规则。")]),t("c6-09-passage-b","passage","听力篇章2","2017 年报道讨论以电视空白频段、传感器、航拍与共享模式降低精准农业门槛；不把研发目标写成已实现。",[e("c6-09-passage-b",12,"What assumption about farmland underlies precision agriculture?",["Soil conditions can differ even within one field.","Farms with the same crop have nearly identical water needs.","Aerial pictures are more reliable when no ground data are available.","The most productive fields are those using the same input everywhere."],["natural differences in the soil"],"精准农业立足于同一块田内部也有差异，才能按区域调整用种、肥、水。不能把同作物等同同需水；航拍与地面数据是互补，不是排除地面资料；均匀投入亦非文中原则。"),e("c6-09-passage-b",13,"What role do unused television channels play in Chandra’s system?",["They provide long-distance links between sensing equipment.","They broadcast planting instructions to farmers’ home televisions.","They power soil sensors when electricity is unavailable.","They replace the aerial photographs used to map the fields."],["connects soil sensors","white space"],"闲置电视频率提供长距离宽带连接，把传感器等设备接起来。不是普通电视节目教学、供电方式，也没有取代航拍；这些角色必须分清。"),e("c6-09-passage-b",14,"How does the artificial intelligence help create a fuller picture of the farm?",["It combines aerial photographs with sensor data to map soil needs.","It replaces field sensors with photographs of healthy cattle.","It sends the same fertilizer schedule to farms in different countries.","It sets crop prices using the photographs collected by phone apps."],["AI) compares these aerial photos"],"AI 比对航拍与传感器数据，形成酸度、缺水等分布图。牲畜摄像另作示例，不替代土壤传感器；统一施肥表、根据图片定价都非这里的输出。"),e("c6-09-passage-b",15,"Why does the report remain cautious about how quickly these technologies will spread?",["New practices must fit people’s existing farming and business methods.","The system cannot use alternatives to expensive drone aircraft.","No companies beyond Microsoft are interested in farm technology.","GPS information is still unavailable to the general public."],["use it with their existing methods","Different countries have different"],"结尾强调实施靠人，各国农法和经营方式不同，采用速度未明。前文明确有手机系气球等低价替代、多家企业参与，GPS 自 1990 年代已向公众开放，不能用这些相反说法解释谨慎态度。")]),t("c6-09-talk-a","talk","报告与讲解1","2009–2017 年美国机器人就业研究区分全国增长缓冲与地区、群体受损，并提出再培训。均为历史研究内容。",[e("c6-09-talk-a",16,"What softened the national employment impact of workplace robots in the period studied?",["Economic growth helped absorb some displaced workers.","Robots were moved from Midwest factories to other countries.","Manufacturers reduced their use of robots after the recession.","Employers replaced repetitive robot tasks with manual production."],["effect robots had","growing economy independent"],"研究说衰退后的经济增长在全国层面吸收了部分失业者，缓和影响；不是机器人外迁、数量下降或改回手工。录音开头反而说机器人数量翻倍。"),e("c6-09-talk-a",17,"Why can displacement put downward pressure on workers’ pay, according to Rodgers?",["Workers can crowd into industries where demand is not growing fast enough.","Robot manufacturers require their customers to standardise wages.","Workers can retain their former salaries only by moving to Midwest states.","Industrial robots need increasing numbers of daily maintenance workers."],["oversupply of workers","demand for workers is not growing"],"岗位转移使某些行业劳动力过剩，若需求追不上便压低工资。机器人厂商定薪、迁往中西部保薪、维护岗位激增都不是 Rodgers 给的机制。"),e("c6-09-talk-a",18,"What response does Rodgers urge during a period of prosperity?",["Invest in education and training that prepare displaced workers for new careers.","Delay assistance until national employment figures begin to fall.","Direct displaced workers back to the same repetitive manufacturing tasks.","Require workers to accept lower pay before offering career support."],["Assistance programs should include","Times of prosperity"],"他主张景气时就投资教育、技能训练，为新职业铺路，而非等全国就业转坏。回到原来重复工序、先接受降薪再援助，都不是提出的条件。")]),t("c6-09-talk-b","talk","报告与讲解2","2018 年开普敦 Day Zero 预测推迟后，节水限制仍在；公众对危机传播评价不一。不是当前供水状态。",[e("c6-09-talk-b",19,"What changed when officials postponed the predicted Day Zero?",["The predicted date changed, while severe water restrictions remained.","Households were allowed more than twice their previous daily water limit.","The city stopped monitoring its dam levels until the next summer.","The government announced that the drought itself had ended."],["canceled the prediction","Severe water restrictions remain"],"延后的是预计缺水日，50 升每日限额等严限继续，直到供水恢复到可接受水平。不是限额翻倍、停止监测，也没有宣布干旱已结束。"),e("c6-09-talk-b",20,"Why did some residents feel tricked by the Day Zero warning?",["They believed it was a campaign to change behaviour rather than a real threat.","They believed restrictions had been removed before water supplies recovered.","They thought officials had kept the predicted date secret from the public.","They thought the city was selling saved water to private companies."],["other people think they were tricked"],"这是报道转述一部分人的看法：认为城市并无完全断水危险，只是宣传促行为改变。题目并不认定该怀疑属实；限令提前取消、日期保密和卖水均未被列为原因。"),e("c6-09-talk-b",21,"What observation supports Pengelly’s positive assessment of the warning?",["Overall water use stayed down after the immediate threat passed.","Residents returned to taking long baths after the date was delayed.","The daily allowance was increased when public criticism began.","The city no longer needed the arrival of seasonal rainfall."],["overall water usage did not rise"],"她以威胁过去后整体用水未反弹支持节约习惯改变。长浴仍是她一年多未实现的愿望；没有说限额提高，也没有说不再需要降雨。")]),t("c6-09-talk-c","talk","报告与讲解3","ORPC 以河流和潮流发电服务偏远社区，介绍部署、浅水适应、潮流变化及稳定输出研发。成本仅属当时报价。",[e("c6-09-talk-c",22,"For which users was ORPC’s technology principally designed, according to Sauer?",["Small rural communities with limited access to power sources.","Large coastal factories seeking to replace their entire energy grid.","Fishing boats that need a generator while moving between ports.","City households that already receive inexpensive natural-gas power."],["designed for small, rural communities"],"Sauer 定位的是电源不易取得的小型乡村社区。大型工厂整网替换、航行渔船、市区低价天然气用户并非所说的主要对象。"),e("c6-09-talk-c",23,"What happens after the RivGen pontoon has been fixed in position?",["It is flooded so the assembly sinks and the current turns the turbines.","It floats downstream to measure where the river current is strongest.","It raises the generator above water so wind can turn the turbines.","It carries the generator to shore whenever the tide begins to rise."],["Once the pontoon boat is fixed"],"固定后给浮台注水，使浮台、框架、发电机沉到河底，由水流驱动。不是随流测量、抬到空中捕风，或涨潮搬回岸上。"),e("c6-09-talk-c",24,"What advantage of the generator’s size does Sauer emphasise?",["Its low height allows it to operate in relatively shallow water.","Its narrow cage allows it to pass through crowded shipping channels.","Its large pontoon keeps it floating near the river surface.","Its tall frame places the turbines above passing fish."],["generator is not very tall"],"原话将机组不高与适用浅水联系起来。狭窄航道、保持水面漂浮、让涡轮高过鱼群均未被说成尺寸优势，且浮台实际会下沉。"),e("c6-09-talk-c",25,"What improvement are ORPC workers seeking for TidGen?",["A steadier power output despite changes in tidal strength.","A design that obtains most of its power from sunlight.","A system that shuts down whenever the tide changes direction.","A method that replaces the main energy grid with isolated turbines."],["power TidGen can harvest changes","make the power output steady"],"目前输出随潮强变化，研发目标是使之稳定并将来接入主电网。不是改捕太阳能、潮向变就停机，或用孤立机组替代电网；跨流涡轮还可应对水流方向变化。")])]},w={number:10,theme:"公众行动、协作与社会转型",recordings:[t("c6-10-dialogue-a","conversation","长对话1","原创教学故事中，Anna 把遭雷击幻想成超级英雄起源，陌生青年则反复劝她求助。虚构情节不作现实安全指导。",[e("c6-10-dialogue-a",1,"Why does Anna urge the young man to decide soon about the convention?",["Tickets sold out the previous year.","The organisers have moved it to an earlier date.","She needs a partner before she can buy a ticket.","The young man has been invited to perform there."],["Last year, it sold out"],"Anna 给出的理由是上年售罄，提醒尽早决定；没有提前日期、必须搭伴买票或青年受邀演出的信息。"),e("c6-10-dialogue-a",2,"How do Anna and the young man differ in their stated superhero preferences?",["Anna prefers an accidental transformation; he prefers being born with powers.","Anna prefers being born with powers; he prefers an accidental transformation.","Anna wants to become invisible; he wants to learn to fly.","Anna wants to read minds; he wants to live in a treehouse."],["YOUNG MAN: Okay.","ANNA: I’d rather become a superhero by an unexpected accident!"],"最初假设题里青年选天生，Anna 选意外获得。隐身、飞行、读心和树屋是后来的尝试或 Anna 猜别人想法，不是两人对最初两选项的表态。"),e("c6-10-dialogue-a",3,"What does the young man repeatedly recommend after the lightning strike?",["Anna should see a doctor or get help.","Anna should test her powers at the convention.","Anna should change her superhero name.","Anna should teach him to become invisible."],["You’d better see a doctor","really should get some help"],"青年多次劝就医、寻求帮助，与 Anna 自认获得超能力形成反差。他没有鼓励到大会测试或教他隐身；英雄名来自 Anna 自己。"),e("c6-10-dialogue-a",4,"Why does Anna finally choose to walk?",["She cannot fly, and using a ride service everywhere would be expensive.","She wants to find the young man’s treehouse before the convention.","She has been told that walking will restore her lost powers.","She needs to avoid being recognised while she is invisible."],["expensive to Uber everywhere"],"她说飞行也不是自己的能力，老叫车太贵，加上天气不错于是步行。树屋只是读心猜测；恢复能力、隐身避认都不是这次步行的理由。")]),t("c6-10-dialogue-b","conversation","长对话2","续篇中 Anna 学习闪电知识、尝试帮助露营者，最后重新以普通人的身份加入活动。保留过去完成进行时教学。",[e("c6-10-dialogue-b",5,"What is Anna’s plan for discovering her supposed superpowers?",["Learn more about lightning by reading about it.","Ask the announcer to demonstrate a new ability.","Return to the convention and interview other heroes.","Practise reading the young man’s mind until he agrees."],["need to learn about lightning","read many books"],"她提出先了解闪电，并阅读许多书。旁白此时承担语法讲解，不演示能力；回大会采访、让青年认可读心术也非该计划。"),e("c6-10-dialogue-b",6,"Why have the children been unable to make their campfire?",["Their firewood is too wet to burn.","They have used their last matches to charge a phone.","They have been told to wait until the rain stops.","Their parent has asked them to save the wood for later."],["wood will never burn","too wet"],"家长明确说木柴太湿，孩子此前试了一个多小时。手机充电是之前的另一场景；等待雨停和要求留柴都不是这里已给的阻碍。"),e("c6-10-dialogue-b",7,"What additional help does Anna offer the children after they thank her?",["She offers to collect more firewood.","She offers to bring them a new telephone.","She offers to teach them to toast marshmallows.","She offers to carry the campfire indoors."],["don’t have enough firewood"],"Anna 认为木柴不够，打算用自己所谓超级竞走去取更多。手机属于前一个人的请求；烤棉花糖是孩子的目的，不等于她开课，亦未提出搬火入室。"),e("c6-10-dialogue-b",8,"What does the young man propose after Anna says she has lost her powers?",["Go inside and eat S’mores because it is starting to rain.","Return to the wall to practise walking through it.","Read another lightning book before the next storm.","Visit the convention to obtain a replacement superhero suit."],["Do you want to go inside"],"他提议因下雨进屋吃 S’mores，结尾回到普通人的相处。墙和闪电书属于前情，换战衣、回大会都未被提为下一步。")]),t("c6-10-passage-a","passage","听力篇章1","尼日利亚创业者把废塑料袋做成日常用品，面对卫生观感、使用场合与盈利挑战。",[e("c6-10-passage-a",9,"Which sequence describes Samson’s production process?",["Collect used bags, wash them, and sew them into products.","Buy finished clothes, remove their labels, and sell them as recycled goods.","Collect plastic bottles, melt them, and mould them into school furniture.","Sort new bags by colour, fill them with waste, and use them as building blocks."],["first step in Samson’s process"],"报道说从垃圾场收用过的袋子，洗净后缝制。没有改标衣物、熔瓶制家具，或用新袋装垃圾做砖的工艺。"),e("c6-10-passage-a",10,"How do Emmanuel Itiniyi and Victor Anyaese differ in their reactions to Samson’s products?",["One rejects them as dirty, while the other finds them attractive and is willing to use them.","Both like the products but say they are unsuitable for schoolchildren.","One objects to their price, while the other wants the designs changed.","Both refuse to wear the products but would use them as car covers."],["Emmanuel Itiniyi of Lagos says the products are dirty","I won’t allow my child","others are more accepting","Yes I can use it"],"Itiniyi 认为产品脏，不愿让孩子把它们当衣服或书包带去学校；Anyaese 更能接受，说看图片觉得好看、自己可以使用。两人的态度相反，不能改成共同赞同或拒绝。价格和改设计不是这里的分歧，书包及车罩的产品用途也不等于两人都同意使用。该题不依赖休闲用途的尾句。"),e("c6-10-passage-a",11,"How does the report characterise Samson’s business at this point?",["Not yet profitable, but intended to encourage environmental action.","Already profitable enough to fund the city’s waste collection.","Mainly supported by school orders rather than public purchases.","Temporarily closed while a new raincoat design is being tested."],["business is not profitable yet"],"结尾说尚未盈利，但他希望推动青年和掌权者保护环境。没有盈利支付全城清运、学校订单为主或停业测试雨衣的叙述。")]),t("c6-10-passage-b","passage","听力篇章2","2018 年报道用空间站运输与 Apollo–Soyuz 历史说明政治竞争中的航天合作。运输依赖和未来预测仅限当时报导。",[e("c6-10-passage-b",12,"Why does the report contrast the launch with wider US–Russian relations?",["Space cooperation is continuing despite increased political tensions.","The launch marks the start of joint work after political disputes ended.","The two countries have moved their space programmes to a neutral state.","The launch has caused both countries to suspend work on the space station."],["Yet experts note"],"报道的转折在于政治紧张升高，航天却继续合作。不是矛盾解决后才合作；哈萨克斯坦发射地点不等于迁移全部计划，也没有暂停空间站任务。"),e("c6-10-passage-b",13,"According to Lewis, why was Russian cooperation especially important for NASA at that time?",["NASA was developing new spacecraft and relied on the Soyuz service.","NASA had decided to stop developing spacecraft for human missions.","The Soyuz was the only craft capable of landing humans on the Moon.","Russia had taken over the work of operating the entire space station."],["since 2011, NASA","Soyuz, which has been operational"],"Lewis 说美国正在发展下一代飞船，其间依赖俄罗斯已有的 Soyuz 载人服务。这不等于放弃研发，也未说 Soyuz 登月或俄方独自运营空间站。"),e("c6-10-passage-b",14,"What does the 1975 Apollo–Soyuz example demonstrate in Lewis’s account?",["The two sides could collaborate even at a politically difficult time.","The space race began when the spacecraft first docked together.","Joint spacecraft had removed the dangers of human space travel.","Political leaders required the two programmes to use identical equipment."],["Apollo spacecraft linked up","even in the height of the Cold War"],"握手对接表明冷战紧张时期仍可共同完成任务并建立信任；不是太空竞赛起点。合作朝安全努力，不是消除全部风险，也未统一所有设备。"),e("c6-10-passage-b",15,"Why does Lewis expect cooperation to remain important for missions to the Moon or Mars?",["Making those destinations habitable would require extensive money and resources.","Existing international rules prohibit countries from travelling there independently.","The space station is scheduled to be physically moved to those destinations.","The Soyuz has already been selected as the permanent vehicle for both missions."],["make either the Moon or Mars habitable"],"她的论证依据是使月球、火星适合人类居住需要巨大资金与资源。原文没有独行禁令、移动空间站或永久指定 Soyuz 的计划，不能把合作必要性变成这些制度结论。")]),t("c6-10-talk-a","talk","报告与讲解1","2019 年 Wyoming 煤业转型报道把成本竞争与碳捕获研发并置，区分地方期望、试验和商业成熟。",[e("c6-10-talk-a",16,"What explanation do industry experts emphasise for coal-fired plants’ difficulties?",["Lower-cost natural gas and growing competition from renewable power.","A sudden shortage of coal close to the surface in Wyoming.","Falling electricity demand caused chiefly by the closure of local mines.","A requirement that every coal plant immediately install carbon-capture equipment."],["rise in popularity of natural gas","solar and wind power"],"专家强调天然气较便宜、风光成本变化切入煤炭市场，与一些支持者单归咎环保规定的看法区分。Wyoming 煤仍易采；录音没把矿关门说成全国用电需求主因，也无所有电站立即装设备的命令。"),e("c6-10-talk-a",17,"What makes the Integrated Test Center useful for carbon-capture experiments?",["Equipment can be connected directly to a power plant’s exhaust.","It can restart the two mines without seeking new financing.","It can replace the state’s coal production with imported building materials.","Its location removes the need to test emissions from working plants."],["directly connect equipment"],"试验中心设在电厂旁，设备可直接接排气测试捕碳方法。不是代煤矿融资或进口建材的项目，也不是省去对实际排放的测试。"),e("c6-10-talk-a",18,"How should the local hopes for carbon capture be understood from the report?",["As a possible future opportunity while the technology remains under development.","As a completed solution already available to most power companies.","As proof that winning the Carbon XPRIZE will reopen the closed mines.","As a plan limited to storing carbon without creating saleable products."],["still being developed","hope some of the teams"],"报道说离广泛可用还有数年，当地希望团队留下经营，因此是潜在机会，不是已成解决方案。获奖与煤矿重开未建立保证关系；比赛正鼓励把二氧化碳变成可售材料或化学品。")]),t("c6-10-talk-b","talk","报告与讲解2","Mogadishu 垃圾治理涉及基础设施、法规、执行和企业处理渠道，题目区分同姓受访者。为2019年历史报道。",[e("c6-10-talk-b",19,"What infrastructure gap does the report identify at the start?",["The city lacked an official waste-disposal site or recycling centre until recently.","The city’s existing recycling plants could accept paper but not metal.","The main landfill was located beyond the reach of the city’s collection trucks.","The government had closed disposal sites to build new coastal housing."],["did not have an official place"],"开头明确说直到不久前没有正式垃圾处置地点或回收中心。不是已有中心挑材料，也未提出垃圾车够不到原填埋场或为住宅关场的情形。"),e("c6-10-talk-b",20,"What additional need does Hassan Nur emphasise after the landfills are announced?",["Legislation to prevent uncontrolled dumping.","A complete ban on public access to the beaches.","A programme to move the university away from the coast.","A rule requiring households to burn waste before collection."],["no laws to prevent","cannot work without legislation"],"大学教师 Nur 指出缺少防止随处倾倒的法律，认为废物管理离不开立法。这里不是关闭海滩、搬大学或要求先焚烧；焚烧在前文还是城市烟臭问题。"),e("c6-10-talk-b",21,"What obstacle does cleaning-company head Mohamud Yusuf Hassan report after saying his company no longer dumps at sea?",["Difficulty finding a place to dispose of or recycle the collected waste.","A shortage of employees willing to collect waste from the city.","A court order preventing his company from entering the new landfills.","A fall in the amount of waste produced by coastal neighbourhoods."],["We don’t dump into the sea","having trouble finding places"],"企业负责人说已不往海里倾倒，却找不到处置或回收的地方。录音提到雇员三百多人，未说缺人，也没有法院禁入令或沿海垃圾减少的解释。")]),t("c6-10-talk-c","talk","报告与讲解3","Pedal Power Kids 把车辆检查、骑行观察和独立出行结合起来；家长证言补充课程如何服务实际生活。",[e("c6-10-talk-c",22,"What does the “ABC quick check” cover?",["Air in the tyres, working brakes, and a clean chain.","Balance on the bicycle, correct clothing, and clear road signs.","A route through town, bicycle lights, and crossing rules.","Age of the bicycle, a bell, and the condition of its seat."],["A” is for air","chain must be clean"],"ABC 对应 Air、Brakes、Chain，检查胎、刹车及链条清洁。平衡、观察和道路规则也与骑行有关，但不是这项命名检查的三个组成部分。"),e("c6-10-talk-c",23,"Why does Varn teach children to keep their eyes up rather than watching the pedals?",["It helps them see their surroundings and turn properly.","It lets them check tyre pressure while the bicycle is moving.","It prevents them from needing to learn starting and stopping.","It helps them copy the instructor’s pedalling speed exactly."],["look down at the pedals","see what’s going on around"],"低头看踏板会看不清周围，也不利转弯；抬眼朝去处看可改善这些能力。胎压是骑前检查，不能边骑边看出来；起停仍要学，照抄老师速度不是这里的教学目的。"),e("c6-10-talk-c",24,"Why did Julia Roeling enrol her children in the class?",["She lacked both the time and confidence to teach them herself.","Their school required a certificate before they could cycle to class.","She wanted them to train for competitive bicycle races.","Their bicycles needed repairs that the shop had refused to perform."],["neither the time nor the confidence"],"Roeling 说自己既没时间也没把握教，因此让三个孩子中的两个参加。学校证书、赛车训练、商店拒修都不是她给出的报名动机。"),e("c6-10-talk-c",25,"What wider value does Varn attach to teaching children to ride?",["It develops active habits and connects families and communities.","It prepares children to give up other sports as soon as they learn.","It reduces the need for families to discuss road safety together.","It allows classes to focus on equipment rather than travel decisions."],["develop healthy habits","families and communities connected"],"Varn 希望骑行带来健康活动习惯、少污染和家庭社区联系。她用年老仍可骑车说明长期性，不是要求孩子立刻放弃其他运动；安全判断和出行能力本来就是课程目标，不能排除。")])]},y=[m,f,w],b=[{id:"c6-08-dialogue-a",duration:257.96325,rms:.07649074263935668,sha256:"7c123f3aa69e06d53dd5403256e7cbfdbc228bf5ad16c2d8dc6aecf9b01833af",humanReviewed:!1},{id:"c6-08-dialogue-b",duration:281.664,rms:.0952288920080001,sha256:"de1af8c0e51b2bf48622142e17e9de2dbc271ca52181f5596d776bac22acfdcb",humanReviewed:!1},{id:"c6-08-passage-a",duration:225.648,rms:.0673592810874738,sha256:"5270b687c3398ef98f9ce0b03b7cff59ed5ba3991d144709f1bcc3381de5e00f",humanReviewed:!1},{id:"c6-08-passage-b",duration:322.992,rms:.06118487166368165,sha256:"f190436df6f0781b79c61b776c1e07d71aee5ab7d9245eed39f45359c69e23fe",humanReviewed:!1},{id:"c6-08-talk-a",duration:266.83520833333336,rms:.08293958717159677,sha256:"085839bebfeba6caec2f3f3df29c12f3c4b070928ead66db57f3baa007a19a45",humanReviewed:!1},{id:"c6-08-talk-b",duration:493.41597916666666,rms:.04493389970732689,sha256:"da5acaec5346bd23597afae25f70bf1489d43c38f791755883ae9be888a2b092",humanReviewed:!1},{id:"c6-08-talk-c",duration:175.008,rms:.07583313817875983,sha256:"12f65129f7efa1d8128027b395d333c9d63b56254e4013de7f9a5453064b662a",humanReviewed:!1},{id:"c6-09-dialogue-a",duration:246.6939375,rms:.07011272665446958,sha256:"c7a35099e43eb045884c25f521039c45b71da5d3dfacbf5166a601ebc6fa3e26",humanReviewed:!1},{id:"c6-09-dialogue-b",duration:287.784,rms:.05913853014193241,sha256:"b90e0765012579c589bd4f8876d01ea87565f8003396014e1d7236d1f29d5d66",humanReviewed:!1},{id:"c6-09-passage-a",duration:323.448,rms:.04759172907804544,sha256:"c8fda71ba30506680c89a2f93152f54d0d350702c18c3f7ed610432d7d848ef3",humanReviewed:!1},{id:"c6-09-passage-b",duration:467.6602916666667,rms:.05584303410360455,sha256:"bdd7e91adc21959b95cec47b12cef6bb63e6ae62ee3fb6fbfdc0130ad8344789",humanReviewed:!1},{id:"c6-09-talk-a",duration:251.61597916666668,rms:.11996156759401307,sha256:"34a200c053636082f9ad60e4feb47dec25ca5a88ebc29660695ea3ad37bfbaf0",humanReviewed:!1},{id:"c6-09-talk-b",duration:225.81597916666666,rms:.022980729120797357,sha256:"f9a42ae23f6f17b00ff241397d1ab64369a1668f10cefb2227bb11d29a1bac61",humanReviewed:!1},{id:"c6-09-talk-c",duration:232.54202083333334,rms:.06214452368319749,sha256:"2d1ac4fa74f9fdd54209596f9d506ee8562c255d7780c3efbd089265434a41f1",humanReviewed:!1},{id:"c6-10-dialogue-a",duration:288.408,rms:.14035479525339883,sha256:"07b87997f49cacb0f96b59fdfdec4776c75d4d86cdd03d0efc3d3baea52331a2",humanReviewed:!1},{id:"c6-10-dialogue-b",duration:285.5759791666667,rms:.12389588621411286,sha256:"0f30cb5ce6c6338db743bd29048f3eedb54664f6944bc81b15b30e278d98f51a",humanReviewed:!1},{id:"c6-10-passage-a",duration:141.45597916666668,rms:.08166104419274618,sha256:"dc59f001c05257990f999d1f64fc27c6a5cf7592c21e3e5baac47ac6af29dc5f",humanReviewed:!1},{id:"c6-10-passage-b",duration:266.184,rms:.0633780605257398,sha256:"69fbe8aa2f237bd36675d7feb44645ee118ed1e5d99c43c4859e4c9813260cd1",humanReviewed:!1},{id:"c6-10-talk-a",duration:382.51208333333335,rms:.040536952909061466,sha256:"d0e212d12e17dba5386d48e5d15148e62224e69254e25cd92e14fb96a864bdd0",humanReviewed:!1},{id:"c6-10-talk-b",duration:316.128,rms:.01254236348390063,sha256:"6b5b2a1832e8f58266520c0d6c60107bbe51b40eb0529ca5d1970f0ac111d12f",humanReviewed:!1},{id:"c6-10-talk-c",duration:293.088,rms:.04954180347602589,sha256:"f0b0135a30e17b5557746b6fc9a95e990e2f50b2e8bb6ca4a660147763261c5d",humanReviewed:!1}],k=y.map(a=>g(a,c,b));export{k as cet6ListeningSeries08to10};
